import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link, useLocation, useSearchParams } from 'react-router-dom'
import { MdArrowForward, MdClose, MdPayments, MdReceiptLong, MdRefresh, MdSearch } from 'react-icons/md'
import { getBills as getAdminBills } from '../../services/admin.service'
import { getBills as getStaffBills } from '../../services/staff.service'
import { useAuth } from '../../context/AuthContext'
import { hasStaffPermission } from '../../config/staffPermissions'
import { branchPortalPath } from '../../utils/branchPortalPath.mjs'
import { formatMoney, paymentMethodLabel } from '../../utils/billingUi'
import BillingStatusBadge from './BillingStatusBadge'
import Pagination from '../ui/Pagination'
import { normalizedBillingTab, statusQueryFor } from './billingWorkspaceModel.mjs'
import { EmptyState, ErrorState, LoadingState } from '../ui/PageState'

const sections = [{ id: 'payments', label: 'Payments', icon: MdPayments }, { id: 'history', label: 'Receipts & History', icon: MdReceiptLong }]
const paymentTabs = [{ id: 'pending', label: 'Pending' }, { id: 'failed', label: 'Failed' }, { id: 'paid', label: 'Paid' }]
const cleanAmount = value => Number.isFinite(Number(value)) ? Math.max(0, Number(value)) : 0
const settled = bill => bill.status === 'paid'
const failure = bill => bill.latest_gateway_failure_message || bill.latest_gateway_error_code || 'The latest payment attempt failed. Open the bill to review the payment status.'

/** Shared billing workspace. Same visual flow; server permissions still control actions. */
export default function BillingWorkspace({ role = 'admin' }) {
  const staff = role === 'staff'
  const { user } = useAuth()
  const canCheckout = !staff || hasStaffPermission(user, 'checkout')
  const canRead = !staff || canCheckout || hasStaffPermission(user, 'billing')
  const location = useLocation()
  const [params, setParams] = useSearchParams()
  const selectedTab = normalizedBillingTab(params.get('tab'))
  const section = staff && !canCheckout ? 'history' : selectedTab
  const [status, setStatus] = useState(params.get('status') === 'failed' || params.get('tab') === 'payment-issues' ? 'failed' : 'pending')
  const [search, setSearch] = useState('')
  const [method, setMethod] = useState('')
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const [result, setResult] = useState({ items: [], pagination: {} })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const latestRequest = useRef(0)
  const fetchBills = staff ? getStaffBills : getAdminBills
  const portalPath = path => staff ? path : branchPortalPath(path, location.pathname)
  const base = staff ? (location.pathname.startsWith('/staff/checkout') ? '/staff/checkout' : '/staff/billing') : portalPath('/admin/billing')
  const canFilterMethod = section === 'history' || status === 'paid'
  const query = useMemo(() => ({
    status: statusQueryFor(section, status), search: search.trim(),
    payment_method: canFilterMethod ? method : '', date_from: from, date_to: to,
    date_basis: canFilterMethod && method ? 'payment' : 'visit', page, limit: pageSize,
  }), [section, status, search, canFilterMethod, method, from, to, page, pageSize])
  const load = useCallback(async () => {
    if (!canRead) return
    const requestId = ++latestRequest.current
    setLoading(true); setError('')
    try {
      const data = await fetchBills(query)
      if (requestId === latestRequest.current) setResult({ items: Array.isArray(data?.items) ? data.items : [], pagination: data?.pagination || {}, summary: data?.summary || {} })
    } catch (err) { if (requestId === latestRequest.current) setError(err.message || 'Unable to load bills.') }
    finally { if (requestId === latestRequest.current) setLoading(false) }
  }, [canRead, fetchBills, query, location.pathname])
  useEffect(() => {
    const timer = window.setTimeout(() => { void load() }, search ? 250 : 0)
    return () => window.clearTimeout(timer)
  }, [load, search])
  useEffect(() => {
    const onUpdate = () => { void load() }
    window.addEventListener('clinic:refresh', onUpdate)
    return () => window.removeEventListener('clinic:refresh', onUpdate)
  }, [load])
  if (!canRead) return <p role="alert" className="rounded-2xl border border-amber-200 bg-amber-50 p-5">You do not have Billing access.</p>
  const records = result.items || []
  const pagination = result.pagination || {}
  const pendingCount = Number(result?.summary?.draft || 0) + Number(result?.summary?.ready || 0) + Number(result?.summary?.partially_paid || 0)
  const historyPath = id => staff ? `${base}/history/${id}` : portalPath(`/admin/billing/transactions/${id}`)
  const checkoutPath = id => staff ? `/staff/checkout/${id}` : portalPath(`/admin/billing/checkout/${id}`)
  const showSection = next => { setParams({ tab: next }, { replace: false }); setPage(1); setMethod('') }
  const changeStatus = next => { setStatus(next); setPage(1); setMethod('') }
  const clear = () => { setSearch(''); setMethod(''); setFrom(''); setTo(''); setPage(1) }
  return <main className="mx-auto w-full max-w-7xl space-y-5" aria-label="Billing workspace">
    <header className="flex flex-wrap items-start justify-between gap-3">
      <div><h1 className="text-2xl font-black text-slate-900">Billing</h1><p className="mt-1 text-sm text-slate-500">Review bills, collect payments and find receipts in one place.</p></div>
      <button type="button" onClick={() => void load()} className="button-secondary"><MdRefresh/> Refresh</button>
    </header>
    <nav aria-label="Billing sections" className="flex flex-wrap gap-2 border-b border-slate-200 pb-3">
      {sections.filter(tab => !(staff && !canCheckout && tab.id === 'payments')).map(tab => {
        const Icon = tab.icon
        return <button type="button" key={tab.id} onClick={() => showSection(tab.id)} aria-current={section === tab.id ? 'page' : undefined}
          className={`inline-flex min-h-11 items-center gap-2 rounded-xl px-4 text-sm font-bold transition-colors ${section === tab.id ? 'bg-slate-900 text-white' : 'border border-slate-200 bg-white text-slate-700 hover:bg-slate-50'}`}><Icon/>{tab.label}</button>
      })}
    </nav>
    {section === 'payments' && <div className="flex flex-wrap gap-2" role="group" aria-label="Payment status">
      {paymentTabs.map(tab => <button type="button" key={tab.id} onClick={() => changeStatus(tab.id)} aria-pressed={status === tab.id}
        className={`min-h-10 rounded-xl px-4 text-sm font-bold ${status === tab.id ? 'bg-emerald-700 text-white' : 'border border-slate-200 bg-white text-slate-700 hover:bg-slate-50'}`}>{tab.label}{tab.id === 'pending' && status === 'pending' && !loading ? ` (${pendingCount})` : ''}</button>)}
    </div>}
    <section aria-label="Search and filter bills" className="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-2 xl:grid-cols-[minmax(0,1fr)_190px_180px_180px_auto] xl:items-end">
      <label className="block"><span className="mb-1 block text-xs font-semibold text-slate-600">Search bills</span><span className="relative block"><MdSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className="form-control pl-10" value={search} onChange={e => { setSearch(e.target.value); setPage(1) }} placeholder="Patient or bill number" /></span></label>
      {canFilterMethod && <label className="block"><span className="mb-1 block text-xs font-semibold text-slate-600">Payment method</span><select className="form-control" value={method} onChange={e => { setMethod(e.target.value); setPage(1) }}><option value="">All methods</option><option value="cash">Cash</option><option value="gcash">GCash</option><option value="maya">Maya</option><option value="bank_transfer">Bank transfer</option><option value="qrph">QR Ph</option></select></label>}
      <label className="block"><span className="mb-1 block text-xs font-semibold text-slate-600">From</span><input type="date" className="form-control" value={from} onChange={e => { setFrom(e.target.value); setPage(1) }}/></label>
      <label className="block"><span className="mb-1 block text-xs font-semibold text-slate-600">To</span><input type="date" min={from || undefined} className="form-control" value={to} onChange={e => { setTo(e.target.value); setPage(1) }}/></label>
      <button type="button" onClick={clear} className="button-secondary">Clear</button>
    </section>
    {from && to && from > to ? <p role="alert" className="rounded-xl bg-rose-50 p-4 text-sm text-rose-700">The end date must be on or after the start date.</p> :
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm" aria-label="Bills">
      <div className="flex items-center justify-between gap-3 border-b border-slate-100 px-4 py-3"><h2 className="font-bold text-slate-900">{section === 'history' ? 'Receipts & History' : `${paymentTabs.find(tab=>tab.id === status)?.label} Payments`}</h2><span className="text-xs text-slate-500">{pagination.total ?? records.length} bill(s)</span></div>
      {loading ? <div className="p-5"><LoadingState label="Loading bills…" /></div>
        : error ? <div className="p-5"><ErrorState message={error} onRetry={load}/></div>
        : records.length === 0 ? <div className="p-5"><EmptyState title="No bills found" description="Try a different date range or search." /></div>
        : <div className="divide-y divide-slate-100">{records.map(bill => {
            const amountDue = cleanAmount(bill.balance_amount ?? (Number(bill.total_amount || 0) - Number(bill.paid_amount || 0)))
            const to = section === 'history' || status === 'paid' || !canCheckout ? historyPath(bill.id) : checkoutPath(bill.id)
            return <article key={bill.id} className="flex flex-wrap items-center justify-between gap-3 px-4 py-4 hover:bg-slate-50 sm:px-5">
              <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><strong className="text-sm text-slate-900">{bill.patient_name || 'Patient'}</strong><BillingStatusBadge status={bill.status}/>{status === 'failed' && <span className="rounded-lg bg-rose-50 px-2 py-1 text-xs font-semibold text-rose-700">Payment failed</span>}</div>
                <p className="mt-1 text-xs text-slate-500">Bill #{bill.id} · {bill.doctor_name || 'Doctor'} · {bill.appointment_date || '—'}</p>
                <p className="mt-1 text-sm text-slate-600">{bill.appointment_reason || 'Clinic consultation'}</p>
                {status === 'failed' && section === 'payments' && <p className="mt-2 max-w-lg text-xs text-rose-700">{failure(bill)}</p>}
                {settled(bill) && <p className="mt-1 text-xs text-slate-500">{(Array.isArray(bill.payment_methods) ? bill.payment_methods : []).map(paymentMethodLabel).join(', ')}</p>}
              </div>
              <div className="flex flex-wrap items-center gap-3 sm:gap-5"><div className="text-right"><p className="text-xs text-slate-500">{section === 'history' && settled(bill) ? 'Total' : 'Balance due'}</p><p className="text-lg font-black tabular-nums text-slate-900">{formatMoney(section === 'history' && settled(bill) ? bill.total_amount : amountDue)}</p></div>
                <Link to={to} className="button-secondary inline-flex items-center gap-1">{section === 'history' || status === 'paid' || !canCheckout ? 'View Bill' : status === 'failed' ? 'Review Payment' : 'Bill Checkout'} <MdArrowForward/></Link></div>
            </article>
          })}</div>}
      <div className="p-3"><Pagination page={pagination.page || page} totalPages={pagination.totalPages || 1} pageSize={pageSize} total={pagination.total || 0} disabled={loading} onPageChange={setPage} onPageSizeChange={size => {setPageSize(size);setPage(1)}} /></div>
    </section>}
  </main>
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { NavLink, Outlet, useNavigate } from 'react-router-dom'
import { useAuth } from '../../context/AuthContext'
import { useTheme } from '../../context/ThemeContext'
import NotificationBell from '../NotificationBell'
import ProfileAvatar from '../ProfileAvatar'
import { useSSE } from '../../hooks/useSSE'
import { playNotificationSound } from '../../utils/notificationSound'
import { getDashboard } from '../../services/admin.service'
import {
  MdDashboard, MdEventAvailable, MdPeople, MdMedicalServices, MdCalendarToday, MdInventory2,
  MdBarChart, MdChevronLeft, MdLogout, MdAdminPanelSettings, MdMenu, MdClose, MdSettings,
  MdDarkMode, MdLightMode, MdLanguage, MdEdit, MdPayments, MdHistory, MdTune, MdCampaign,
} from 'react-icons/md'

const GROUPS = [
  { label: 'Overview', items: [{ name: 'Dashboard', path: '/admin', icon: MdDashboard, short: 'Home' }] },
  { label: 'Clinic Operations', items: [
    { name: 'Appointments', path: '/admin/appointments', icon: MdEventAvailable, short: 'Appts', badge: 'pending' },
    { name: 'Patient Records', path: '/admin/patient-records', icon: MdPeople, short: 'Patients' },
    { name: 'Doctor Schedules', path: '/admin/doctor-schedules', icon: MdCalendarToday, short: 'Schedule' },
  ] },
  { label: 'Billing & Stock', items: [
    { name: 'Billing', path: '/admin/billing', icon: MdPayments, short: 'Billing' },
    { name: 'Inventory', path: '/admin/inventory', icon: MdInventory2, short: 'Stock' },
  ] },
  { label: 'People & Setup', items: [
    { name: 'Accounts', path: '/admin/accounts', icon: MdPeople, short: 'Accounts' },
    { name: 'System Setup', path: '/admin/system-setup', icon: MdTune, short: 'Setup' },
    { name: 'Announcements', path: '/admin/announcements', icon: MdCampaign, short: 'News' },
  ] },
  { label: 'Insights & System', items: [
    { name: 'Reports', path: '/admin/reports', icon: MdBarChart, short: 'Reports' },
    { name: 'Audit Logs', path: '/admin/audit-logs', icon: MdHistory, short: 'Audit' },
    { name: 'Landing Page', path: '/admin/landingpage', icon: MdLanguage, short: 'Site' },
  ] },
]

const AdminLayout = ({ base = '/admin', branch = null, superBranch = false, permissions = null }) => {
  const { user, logout: clearAuth } = useAuth()
  const { theme, toggleTheme } = useTheme()
  const [collapsed, setCollapsed] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [loggingOut, setLoggingOut] = useState(false)
  const [logoutError, setLogoutError] = useState('')
  const [pending, setPending] = useState(0)
  const navigate = useNavigate()

  const loadCounts = useCallback(() => {
    if (branch) return fetch(`/api/branches/${superBranch ? `workspace/${branch.id}` : 'my'}/dashboard`, { credentials:'include' })
      .then(r => r.ok ? r.json() : null).then(d => setPending(Number(d?.pending || 0))).catch(() => {})
    return getDashboard().then(data => setPending(Number(data?.pendingApprovals || 0))).catch(() => {})
  }, [branch?.id, superBranch])
  useEffect(() => { loadCounts() }, [loadCounts])

  const handleSSEMessage = useCallback((eventName) => {
    if (eventName === 'notification_created') playNotificationSound()
    if (['notification_created','appointment_updated','queue_updated','consultation_saved','billing_finalized','billing_paid'].includes(eventName)) {
      window.dispatchEvent(new CustomEvent('clinic:notifications-refresh'))
      // useSSE centralizes branch-aware data invalidation and refresh delivery.
      if (eventName === 'appointment_updated') loadCounts()
    }
  }, [loadCounts])
  // Each stream resolves branch ownership from its authenticated cookie.
  // Super Admin workspaces receive the explicitly privileged central stream.
  useSSE(superBranch ? 'superadmin' : 'admin', user?.id, handleSSEMessage)

  const handleLogout = async () => {
    if (!window.confirm('Are you sure you want to log out of Carait Clinic?')) return
    setLoggingOut(true); setLogoutError('')
    try { await clearAuth(); navigate(superBranch ? '/superadmin/login' : '/admin/login') }
    catch { setLogoutError('Could not log out. Try again.'); setLoggingOut(false) }
  }

  const visibleGroups = useMemo(() => GROUPS.map(group => ({...group, items:group.items.filter(item => {
    if (branch && item.path === '/admin/landingpage') return false
    if (!branch || superBranch || !permissions) return true
    const key = item.path === '/admin' ? 'dashboard' : ({
      '/admin/appointments':'appointments','/admin/patient-records':'patient_records',
      '/admin/doctor-schedules':'doctor_schedules','/admin/billing':'billing',
      '/admin/inventory':'inventory',
      '/admin/accounts':'accounts','/admin/system-setup':'system_setup','/admin/announcements':'system_setup',
      '/admin/reports':'reports','/admin/audit-logs':'audit_logs'
    })[item.path]
    return !key || permissions.includes(key)
  }) })).filter(group => group.items.length), [branch, superBranch, permissions])
  const portalPath = (path) => `${base}${path.slice('/admin'.length)}`
  // React Router links in the unmodified 07:54 modules still point to /admin.
  // Keep navigation inside the Super Admin's selected branch without rewriting
  // the original module components or letting a privileged user lose context.
  const interceptOriginalLink = event => {
    if (!superBranch || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey) return
    const anchor = event.target.closest?.('a[href]')
    if (!anchor || (anchor.target && anchor.target !== '_self')) return
    const target = new URL(anchor.href, window.location.origin)
    if (target.origin !== window.location.origin || !/^\/admin(?:\/|$)/.test(target.pathname)) return
    event.preventDefault()
    event.stopPropagation()
    navigate(`${portalPath(target.pathname)}${target.search}${target.hash}`)
  }
  const badgeFor = (item) => item.badge === 'pending' ? pending : 0
  const NavItem = ({ item }) => {
    const Icon = item.icon; const badge = badgeFor(item)
    return <NavLink to={portalPath(item.path)} end={item.path === '/admin'} onClick={() => setMobileOpen(false)} className={({ isActive }) => `relative flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium transition-colors group ${isActive ? 'bg-amber-500/15 text-amber-400' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}>
      {({ isActive }) => <>{isActive && <span className="absolute left-0 top-1/2 h-5 w-[3px] -translate-y-1/2 rounded-r-full bg-amber-400" />}<Icon className="shrink-0 text-[19px]" /><span className={`min-w-0 flex-1 whitespace-nowrap transition-all ${collapsed ? 'max-w-0 overflow-hidden opacity-0' : 'max-w-xs opacity-100'}`}>{item.name}</span>{badge > 0 && <span className={`min-w-6 rounded-full bg-amber-400 px-1.5 py-0.5 text-center text-[10px] font-black text-[#0b1a2c] ${collapsed ? 'absolute -right-1 -top-1' : ''}`}>{badge > 99 ? '99+' : badge}</span>}</>}
    </NavLink>
  }

  const mobileNav = useMemo(() => visibleGroups.flatMap(group => group.items).filter(item => ['/admin','/admin/appointments','/admin/billing','/admin/inventory','/admin/reports'].includes(item.path)), [visibleGroups])

  return <div className="flex h-screen overflow-hidden bg-slate-50">
    {mobileOpen && <div className="fixed inset-0 z-40 bg-black/60 backdrop-blur-sm lg:hidden" onClick={() => setMobileOpen(false)} />}
    <aside className={`fixed inset-y-0 left-0 z-50 flex shrink-0 flex-col bg-[#0b1a2c] transition-all duration-300 lg:relative ${collapsed ? 'w-[72px]' : 'w-64'} ${mobileOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
      <div className="flex h-16 shrink-0 items-center gap-3 overflow-hidden border-b border-white/5 px-4"><img src="/logo.png" alt="Carait Clinic" className="h-9 w-9 shrink-0 rounded-xl bg-white/10 object-contain p-1" /><div className={`overflow-hidden whitespace-nowrap leading-tight transition-all ${collapsed ? 'max-w-0 opacity-0' : 'max-w-xs opacity-100'}`}><p className="text-[15px] font-bold text-white">Carait Clinic</p><span className="font-mono text-[10px] font-semibold uppercase tracking-widest text-amber-400">{branch ? (superBranch ? 'Branch Workspace' : 'Branch Admin') : 'Admin Portal'}</span></div><button onClick={() => setMobileOpen(false)} className="ml-auto text-slate-400 lg:hidden"><MdClose className="text-xl" /></button></div>
      <div className={`mx-3 mt-4 rounded-xl border border-white/5 bg-white/5 p-3 ${collapsed ? 'hidden' : ''}`}><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-500/20"><MdAdminPanelSettings className="text-lg text-amber-400" /></div><div className="min-w-0"><p className="truncate text-sm font-bold text-white">{user?.full_name || 'Admin'}</p><p className="text-[10px] font-semibold uppercase tracking-wider text-amber-400">{branch?.name || 'Administrator'}</p></div></div></div>
      {superBranch && <NavLink className={`mx-3 mt-2 block rounded-xl bg-white/10 px-3 py-2 text-xs font-bold text-amber-300 ${collapsed ? 'lg:hidden' : ''}`} to='/superadmin/branches'>← All Branches</NavLink>}
      <nav className="portal-sidebar-scroll flex-1 overflow-y-auto px-3 pb-4 pt-2">{visibleGroups.map((group) => <div key={group.label} className="mb-3"><p className={`mb-1 px-3 text-[10px] font-bold uppercase tracking-[0.16em] text-slate-500 ${collapsed ? 'sr-only' : ''}`}>{group.label}</p><div className="space-y-0.5">{group.items.map((item) => <NavItem key={item.path} item={item} />)}</div></div>)}</nav>
      <div className="shrink-0 border-t border-white/5 px-3 py-4">{logoutError && !collapsed && <p className="px-3 pb-2 text-[10px] text-red-400">{logoutError}</p>}<button onClick={handleLogout} disabled={loggingOut} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-medium bg-red-500/15 text-red-400 hover:bg-red-500/25 hover:text-red-300"><MdLogout className="text-lg" /><span className={collapsed ? 'hidden' : ''}>{loggingOut ? 'Logging out…' : 'Logout'}</span></button></div>
      <button onClick={() => setCollapsed((v) => !v)} aria-label="Toggle sidebar" className="absolute -right-3 top-[72px] hidden h-6 w-6 items-center justify-center rounded-full border border-white/10 bg-[#0b1a2c] text-slate-400 shadow-md lg:flex"><MdChevronLeft className={`text-sm transition-transform ${collapsed ? 'rotate-180' : ''}`} /></button>
    </aside>
    <div className="flex min-h-0 min-w-0 flex-1 flex-col"><header className="z-30 flex h-14 shrink-0 items-center justify-between border-b border-slate-100 bg-white px-4 lg:h-16 lg:px-6"><button onClick={() => setMobileOpen(true)} className="flex h-9 w-9 items-center justify-center rounded-xl border border-slate-200 bg-slate-50 text-slate-500 lg:hidden"><MdMenu className="text-xl" /></button><div className="hidden lg:block" /><div className="flex items-center gap-3"><NotificationBell role={superBranch ? "superadmin" : "admin"} /><button onClick={toggleTheme} className="flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 text-slate-500">{theme === 'dark' ? <MdLightMode /> : <MdDarkMode />}</button><NavLink to={`${base}/settings`} className="flex h-10 w-10 items-center justify-center rounded-xl border border-slate-200 text-slate-500"><MdSettings /></NavLink><div className="hidden items-center gap-2.5 border-l border-slate-100 pl-3 lg:flex"><ProfileAvatar user={user} size="sm" /><div><p className="text-xs font-semibold text-slate-700">{user?.full_name || 'Admin'}</p><p className="text-[10px] text-slate-400">{branch?.name || 'Administrator'}</p></div></div></div></header>
      <main onClickCapture={interceptOriginalLink} className="min-w-0 flex-1 overflow-y-auto p-4 portal-mobile-content lg:p-6"><div className="mx-auto w-full max-w-[1600px]"><Outlet context={{ branch, admin: !superBranch, base, permissions }} /></div></main>
      <nav className="fixed bottom-0 left-0 right-0 z-30 flex portal-mobile-nav items-center justify-around border-t border-slate-100 bg-white px-1 shadow-[0_-4px_20px_rgba(0,0,0,0.06)] lg:hidden">{mobileNav.map((item) => { const Icon=item.icon; const badge=badgeFor(item); return <NavLink key={item.path} to={portalPath(item.path)} end={item.path==='/admin'} className={({isActive})=>`relative flex min-w-[50px] flex-col items-center gap-0.5 rounded-xl px-1 py-1.5 ${isActive?'text-amber-600':'text-slate-400'}`}><Icon className="text-xl" />{badge>0&&<span className="absolute right-0 top-0 min-w-4 rounded-full bg-amber-500 px-1 text-[9px] font-bold text-white">{badge>99?'99+':badge}</span>}<span className="text-[9px] font-bold">{item.short}</span></NavLink>})}</nav>
    </div>
  </div>
}

export default AdminLayout

import { useEffect, useRef, useState } from 'react'
import { documentOps, legacyToOps, encodeDocument } from '../../utils/announcementDocument.mjs'
import 'quill/dist/quill.snow.css'

// Quill is mounted once for each post ID. Parent rerenders do not overwrite the cursor.
export default function QuillAnnouncementEditor({value,onChange}) {
  const target=useRef(null), editor=useRef(null), changed=useRef(onChange)
  const [error,setError]=useState('')
  useEffect(()=>{changed.current=onChange},[onChange])
  useEffect(()=>{
    let cancelled=false,instance=null
    import('quill').then(({default:Quill})=>{
      if(cancelled||!target.current)return
      instance=new Quill(target.current,{
        theme:'snow',placeholder:'Write your clinic announcement here…',
        modules:{toolbar:[[{header:[false,1,2,3]}],['bold','italic','underline','strike'],[{list:'ordered'},{list:'bullet'}],[{align:[]}],['link'],['clean']]},
        formats:['header','bold','italic','underline','strike','list','align','link'],
      })
      editor.current=instance
      instance.setContents({ops:documentOps(value)||legacyToOps(value)},'silent')
      instance.on('text-change',(_d,_old,source)=>{
        if(source!=='user')return
        try{const next=encodeDocument(instance.getContents().ops);setError('');changed.current(next)}
        catch(err){setError(err.message);changed.current('')}
      })
    }).catch(()=>setError('The text editor could not load. Refresh the page and try again.'))
    return ()=>{cancelled=true;editor.current=null;if(target.current)target.current.innerHTML=''}
    // This editor intentionally mounts only when the post key changes.
  },[]) // eslint-disable-line react-hooks/exhaustive-deps
  return <div className="carait-quill overflow-hidden rounded-xl border border-slate-200 bg-white">
    <div ref={target} aria-label="Post content editor" />
    {error&&<p role="alert" className="border-t border-rose-100 bg-rose-50 px-4 py-2 text-sm text-rose-700">{error}</p>}
    <p className="border-t border-slate-100 px-4 py-2 text-xs text-slate-500">Select text to format it. You do not need to type formatting symbols. Paste text only; embedded images are added using Cover Photo.</p>
  </div>
}

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { MdCheckCircle, MdClose, MdError, MdInfo, MdWarning } from 'react-icons/md'

const ToastContext = createContext(null)

const TOAST_STYLES = {
  success: { icon: MdCheckCircle, className: 'toast-success' },
  error: { icon: MdError, className: 'toast-error' },
  warning: { icon: MdWarning, className: 'toast-warning' },
  info: { icon: MdInfo, className: 'toast-info' },
}

const makeId = () => `${Date.now()}-${Math.random().toString(36).slice(2)}`

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([])
  const timers = useRef(new Map())

  const dismiss = useCallback((id) => {
    window.clearTimeout(timers.current.get(id))
    timers.current.delete(id)
    setToasts((current) => current.filter((toast) => toast.id !== id))
  }, [])

  const showToast = useCallback((message, options = {}) => {
    const id = makeId()
    const duration = Math.max(1500, Number(options.duration) || 4000)
    const toast = {
      id,
      message: String(message || 'Something happened.'),
      title: options.title ? String(options.title) : '',
      type: TOAST_STYLES[options.type] ? options.type : 'info',
      duration,
    }

    setToasts((current) => [...current.slice(-4), toast])
    timers.current.set(id, window.setTimeout(() => dismiss(id), duration))
    return id
  }, [dismiss])

  useEffect(() => {
    // Route remaining legacy alert calls through the non-blocking toast system.
    const originalAlert = window.alert
    window.alert = (message) => {
      const text = String(message || '')
      const type = /fail|error|invalid|unable|not found/i.test(text)
        ? 'error'
        : /saved|success|added|updated|completed|confirmed/i.test(text)
          ? 'success'
          : 'info'
      showToast(text, { type })
    }
    return () => {
      window.alert = originalAlert
      timers.current.forEach((timer) => window.clearTimeout(timer))
      timers.current.clear()
    }
  }, [showToast])

  const value = useMemo(() => ({
    showToast,
    dismissToast: dismiss,
    success: (message, options = {}) => showToast(message, { ...options, type: 'success' }),
    error: (message, options = {}) => showToast(message, { ...options, type: 'error' }),
    warning: (message, options = {}) => showToast(message, { ...options, type: 'warning' }),
    info: (message, options = {}) => showToast(message, { ...options, type: 'info' }),
  }), [dismiss, showToast])

  return (
    <ToastContext.Provider value={value}>
      {children}
      <div className="toast-viewport" aria-live="polite" aria-atomic="false">
        {toasts.map((toast) => {
          const config = TOAST_STYLES[toast.type]
          const Icon = config.icon
          return (
            <div key={toast.id} className={`toast-card ${config.className}`} role={toast.type === 'error' ? 'alert' : 'status'}>
              <Icon className="toast-icon" aria-hidden="true" />
              <div className="min-w-0 flex-1">
                {toast.title && <p className="toast-title">{toast.title}</p>}
                <p className="toast-message">{toast.message}</p>
              </div>
              <button type="button" className="toast-close" onClick={() => dismiss(toast.id)} aria-label="Close notification">
                <MdClose />
              </button>
              <span className="toast-progress" style={{ animationDuration: `${toast.duration}ms` }} />
            </div>
          )
        })}
      </div>
    </ToastContext.Provider>
  )
}

export const useToast = () => {
  const context = useContext(ToastContext)
  if (!context) throw new Error('useToast must be used inside ToastProvider.')
  return context
}

import { useEffect, useMemo, useState } from 'react'

const clamp = (value, min, max) => Math.min(Math.max(value, min), max)

export const useClientPagination = (items = [], options = {}) => {
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(Number(options.initialPageSize) || 10)
  const total = Array.isArray(items) ? items.length : 0
  const totalPages = Math.max(1, Math.ceil(total / pageSize))
  const currentPage = clamp(page, 1, totalPages)

  useEffect(() => {
    setPage(1)
  }, options.resetDeps || []) // Reset whenever search/filter inputs change.

  useEffect(() => {
    if (page > totalPages) setPage(totalPages)
  }, [page, totalPages])

  const pageItems = useMemo(() => {
    const start = (currentPage - 1) * pageSize
    return (Array.isArray(items) ? items : []).slice(start, start + pageSize)
  }, [currentPage, items, pageSize])

  const changePageSize = (nextSize) => {
    setPage(1)
    setPageSize(Math.max(1, Number(nextSize) || 10))
  }

  return {
    page: currentPage,
    pageSize,
    total,
    totalPages,
    pageItems,
    setPage,
    setPageSize: changePageSize,
    // Pagination component contract. Keeping the setters above preserves direct hook use.
    onPageChange: setPage,
    onPageSizeChange: changePageSize,
  }
}

export default useClientPagination

import { useEffect, useMemo, useState } from 'react'
import { portalBaseForPath, canManageServicePricingAtPath } from '../../utils/branchPortalPath.mjs'
import { useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { MdAdd, MdArrowBack, MdCheck, MdClose, MdDelete, MdLock, MdPayments } from 'react-icons/md'
import { createBillingCatalogService, deleteBillingCatalogService, getBillingCatalog, getInventory, getSystemSetup, updateBillingCatalogService } from '../../services/admin.service'
import { useToast } from '../../components/ui/ToastProvider'
import ConfirmDialog from '../../components/ui/ConfirmDialog'
import { LoadingState, ErrorState } from '../../components/ui/PageState'
import { formatMoney } from '../../utils/billingUi'

const CLINIC_TYPES = [{ value: 'medical', label: 'General Medicine' }, { value: 'derma', label: 'Dermatology' }]
const blankMaterial = () => ({ inventory_id: '', material_name: '', quantity: 1, unit_label: '', notes: '' })
const DURATION_OPTIONS = Array.from({ length: 16 }, (_, index) => (index + 1) * 30)
const formatDuration = (minutes) => { const total = Number(minutes || 0); const hours = Math.floor(total / 60); const mins = total % 60; if (!hours) return `${mins} minutes`; if (!mins) return `${hours} hour${hours === 1 ? '' : 's'}`; return `${hours} hour${hours === 1 ? '' : 's'} ${mins} minutes` }
const reservedDuration = (minutes) => Math.ceil(Math.max(15, Number(minutes || 60)) / 30) * 30
const blank = { category_id: '', category: '', service_name: '', clinic_type: 'medical', default_price: '', average_duration_minutes: 60, is_active: 1, materials: [] }
const clinicLabel = (value) => CLINIC_TYPES.find((item) => item.value === value)?.label || value
const toForm = (service) => ({
  category_id: service?.category_id || '', category: service?.category || '', service_name: service?.service_name || '',
  clinic_type: ['medical','derma'].includes(service?.clinic_type) ? service.clinic_type : 'medical',
  default_price: Number(service?.consultation_fee ?? 0) > 0
    ? String(Number(service.consultation_fee))
    : (Number(service?.default_price ?? service?.patient_price ?? 0) > 0 ? String(Number(service.default_price ?? service.patient_price)) : ''),
  average_duration_minutes: Number(service?.average_duration_minutes || 60),
  is_active: Number(service?.is_active) === 1 ? 1 : 0,
  materials: Array.isArray(service?.materials) ? service.materials.map((m) => ({ inventory_id: m.inventory_id || '', material_name: m.material_name || m.inventory_name || '', quantity: Number(m.quantity || 1), unit_label: m.unit_label || m.inventory_unit || '', notes: m.notes || '' })) : [],
})

const Admin_BillingServiceForm = () => {
  const { serviceId } = useParams()
  const editing = Boolean(serviceId)
  const navigate = useNavigate()
  const location = useLocation()
  const [searchParams] = useSearchParams()
  const portalBase = portalBaseForPath(location.pathname)
  const canEditPricing = canManageServicePricingAtPath(location.pathname)
  const requestedClinic = ['medical', 'derma'].includes(searchParams.get('clinic')) ? searchParams.get('clinic') : 'medical'
  const toast = useToast()
  const [form, setForm] = useState(() => ({ ...blank, clinic_type: requestedClinic }))
  const [inventory, setInventory] = useState([])
  const [serviceCategories, setServiceCategories] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [step, setStep] = useState(1)
  const [saving, setSaving] = useState(false)
  const [removeOpen, setRemoveOpen] = useState(false)
  const [deleting, setDeleting] = useState(false)
  const [errors, setErrors] = useState({})
  const [dirty, setDirty] = useState(false)
  const [legacyDuration, setLegacyDuration] = useState(null)
  const [serviceUsageCount, setServiceUsageCount] = useState(0)

  const inventoryMap = useMemo(() => new Map(inventory.map((item) => [Number(item.id), item])), [inventory])
  const availableCategories = useMemo(() => serviceCategories
    .filter((category) => category.clinic_type === form.clinic_type && (Number(category.is_active) === 1 || Number(category.id) === Number(form.category_id)))
    .sort((a,b) => String(a.name || '').localeCompare(String(b.name || ''), 'en', { sensitivity: 'base' })), [serviceCategories, form.clinic_type, form.category_id])

  const servicePrice = Math.max(0, Number(form.default_price || 0))
  const isInventoryCompatible = (item, clinicType = form.clinic_type) => Boolean(
    item && !item.archived_at && (!item.category || item.category === clinicType)
  )
  const consumablesTotal = useMemo(() => form.materials.reduce((sum, material) => {
    const item = inventoryMap.get(Number(material.inventory_id))
    if (!isInventoryCompatible(item)) return sum
    const unitPrice = Math.max(0, Number(item?.selling_price || 0))
    const quantity = Math.max(0, Number(material.quantity || 0))
    return sum + (unitPrice * quantity)
  }, 0), [form.materials, inventoryMap, form.clinic_type])
  const patientPrice = Math.round((servicePrice + consumablesTotal) * 100) / 100

  useEffect(() => { (async () => {
    setLoading(true)
    try {
      const [items, setup, catalog] = await Promise.all([getInventory(), getSystemSetup(), editing ? getBillingCatalog({ includeInactive: true }) : Promise.resolve([])])
      setInventory((Array.isArray(items) ? items : []).filter((item) => !item.archived_at))
      const categories = Array.isArray(setup?.service_categories) ? setup.service_categories : []
      setServiceCategories(categories)
      if (editing) {
        const found = (Array.isArray(catalog) ? catalog : []).find((item) => Number(item.id) === Number(serviceId))
        if (!found) throw new Error('Billing service not found.')
        const legacyCategory = !found.category_id ? categories.find((category) => category.clinic_type === found.clinic_type && category.name === found.category) : null
        setForm(toForm({ ...found, category_id: found.category_id || legacyCategory?.id || '' }))
        setLegacyDuration(Number(found.average_duration_minutes))
        setServiceUsageCount(Number(found.usage_count||0))
      }
      setDirty(false)
    } catch (err) { setError(err.message || 'Could not load service editor.') }
    finally { setLoading(false) }
  })() }, [editing, serviceId])

  useEffect(() => {
    const beforeUnload = (event) => { if (!dirty) return; event.preventDefault(); event.returnValue = '' }
    window.addEventListener('beforeunload', beforeUnload)
    return () => window.removeEventListener('beforeunload', beforeUnload)
  }, [dirty])

  const update = (key, value) => { setForm((current) => ({ ...current, [key]: value })); setDirty(true) }
  const changeClinic = (clinicType) => {
    setForm((current) => ({ ...current, clinic_type: clinicType, category_id: '', category: '', materials: [] }))
    setErrors((current) => Object.fromEntries(Object.entries(current).filter(([key]) => !key.startsWith('material_') && !key.startsWith('qty_') && !key.startsWith('price_'))))
    setDirty(true)
    toast.info('Clinic changed. Consumables were cleared so only inventory for the selected clinic can be added.')
  }
  const changeCategory = (categoryId) => { const category = serviceCategories.find((item) => Number(item.id) === Number(categoryId)); setForm((current) => ({ ...current, category_id: categoryId, category: category?.name || '' })); setDirty(true) }
  const updateMaterial = (index, key, value) => { setForm((current) => ({ ...current, materials: current.materials.map((m, i) => i === index ? { ...m, [key]: value } : m) })); setDirty(true) }
  const chooseInventory = (index, value) => {
    const item = inventoryMap.get(Number(value))
    setForm((current) => ({
      ...current,
      materials: current.materials.map((m, i) => i === index
        ? { ...m, inventory_id: value, material_name: item?.name || '', unit_label: value ? 'unit' : '' }
        : m),
    }))
    setDirty(true)
  }
  const openCategorySetup = () => { if (dirty && !window.confirm('You have unsaved service changes. Leave this page and manage Service Categories?')) return; navigate(`${portalBase}/system-setup?tab=service_categories`) }

  const payload = () => ({
    category_id: Number(form.category_id) || null, category: String(form.category || '').trim(), service_name: String(form.service_name || '').trim(), clinic_type: form.clinic_type,
    // consultation_fee stores the base Service Price; default_price stores the final patient price.
    default_price: patientPrice, consultation_fee: servicePrice, average_duration_minutes: Number(form.average_duration_minutes || 60), profit_percentage: 0, is_active: Number(form.is_active) === 1 ? 1 : 0,
    materials: form.materials.map((m, index) => ({ inventory_id: m.inventory_id || null, material_name: String(m.material_name || '').trim(), quantity: Number(m.quantity || 0), unit_label: String(m.unit_label || '').trim(), unit_cost_override: null, notes: String(m.notes || '').trim(), sort_order: index })).filter((m) => m.inventory_id || m.material_name),
  })

  const validate = (target = 3) => {
    const p = payload(); const next = {}
    if (target === 1 || target === 3) {
      if (!p.category_id) next.category = 'Select a service category.'
      if (!p.service_name) next.service_name = 'Enter a service name.'
      if (!(servicePrice > 0)) next.default_price = 'Service Price is required and must be greater than ₱0.00.'
      if (!DURATION_OPTIONS.includes(Number(form.average_duration_minutes)) && !(editing && Number(legacyDuration)===Number(form.average_duration_minutes))) next.average_duration_minutes = 'Choose an appointment length in 30-minute steps, from 30 minutes to 8 hours.'
    }
    if (target === 2 || target === 3) form.materials.forEach((m, i) => {
      const item = inventoryMap.get(Number(m.inventory_id))
      if (!m.inventory_id || !isInventoryCompatible(item)) {
        next[`material_${i}`] = m.inventory_id
          ? 'This inventory item does not belong to the selected clinic. Choose another item.'
          : 'Select an inventory item.'
      }
      if (!(Number(m.quantity) > 0) || !Number.isInteger(Number(m.quantity))) next[`qty_${i}`] = 'Quantity must be a whole number greater than zero.'
      if (m.inventory_id && isInventoryCompatible(item) && !(Number(item?.selling_price || 0) > 0)) next[`price_${i}`] = 'Set a Selling Price for this inventory item before using it as a consumable.'
    })
    setErrors(next); return Object.keys(next).length === 0
  }
  const move = (next) => { if (next > step && !validate(step)) { toast.warning('Check the highlighted fields before continuing.'); return } setStep(next); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const save = async () => {
    if (!validate(3)) { toast.warning('Check the service details before saving.'); return }
    setSaving(true)
    try { editing ? await updateBillingCatalogService(serviceId, payload()) : await createBillingCatalogService(payload()); setDirty(false); toast.success(editing ? 'Billing service updated.' : 'Billing service added.'); navigate(`${portalBase}/system-setup/billing/services`) }
    catch (err) { toast.error(err.message || 'Billing service could not be saved.') }
    finally { setSaving(false) }
  }
  const remove = async () => { setDeleting(true); try { const result = await deleteBillingCatalogService(serviceId); toast.success(result?.message || 'Service removed.'); setDirty(false); navigate(`${portalBase}/system-setup/billing/services`) } catch (err) { toast.error(err.message || 'Service could not be removed.') } finally { setDeleting(false) } }
  const leaveEditor = () => { if (dirty && !window.confirm('You have unsaved service changes. Leave this page and discard them?')) return; navigate(`${portalBase}/system-setup/billing/services`) }

  if (loading) return <div className="mx-auto max-w-5xl"><LoadingState label="Loading service editor..." /></div>
  if (error) return <div className="mx-auto max-w-5xl"><ErrorState message={error} onRetry={() => window.location.reload()} /></div>
  if (!canEditPricing) return <div className="mx-auto max-w-3xl"><div className="rounded-3xl border border-slate-200 bg-white p-8 shadow-sm"><div className="flex items-start gap-4"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-slate-100 text-slate-500"><MdLock className="text-xl" /></div><div><h1 className="text-xl font-black text-slate-900">Services & Pricing is Admin-only</h1><p className="mt-2 text-sm text-slate-500">Staff can review configured services and prices, but only an Admin can add services or change Service Price and consumable pricing.</p><button className="button-secondary mt-5" onClick={() => navigate(`${portalBase}/system-setup/billing/services`)}><MdArrowBack /> Back to Services & Pricing</button></div></div></div></div>

  return <div className="mx-auto max-w-5xl space-y-5">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div><button className="mb-2 inline-flex items-center gap-1 text-sm font-bold text-slate-500 hover:text-slate-900" onClick={leaveEditor}><MdArrowBack /> Services & Pricing Setup</button><h1 className="flex items-center gap-2 text-2xl font-black text-slate-900"><MdPayments className="text-amber-500" /> {editing ? 'Edit Service' : 'Add Service'}</h1><p className="mt-1 text-sm text-slate-500">Set the Service Price and the inventory consumables normally used. Consumable Selling Prices are added automatically to the patient price.</p></div>
      {editing && (Number(form.is_active)===1 || serviceUsageCount===0) && <button className="button-danger" onClick={() => setRemoveOpen(true)}><MdDelete /> {serviceUsageCount>0?'Deactivate Service':'Delete Service'}</button>}
    </div>

    <div className="grid grid-cols-3 gap-2 rounded-2xl bg-slate-100 p-1 text-sm font-bold">
      {['Service Details','Supplies','Review'].map((label,index)=><div key={label} className={`rounded-xl px-3 py-2 text-center ${step===index+1?'bg-white text-slate-900 shadow-sm':'text-slate-500'}`}>{index+1}. {label}</div>)}
    </div>

    <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
      {step === 1 && <div className="space-y-5">
        <div><h2 className="text-lg font-black">Service Details</h2><p className="mt-1 text-sm text-slate-500">Service Price covers the service itself. Selected consumables are added using their Inventory Selling Price.</p></div>
        <div className="grid gap-4 sm:grid-cols-2">
          <label><span className="form-label">Clinic *</span><select className="form-control mt-1.5" value={form.clinic_type} onChange={(e)=>changeClinic(e.target.value)}>{CLINIC_TYPES.map((option)=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label>
          <label><span className="form-label">Service Category *</span><select className="form-control mt-1.5" value={form.category_id} onChange={(e)=>changeCategory(e.target.value)}><option value="">Select category</option>{availableCategories.map((option)=><option key={option.id} value={option.id}>{option.name}</option>)}</select>{!availableCategories.length&&<p className="form-helper">No active categories. <button type="button" className="font-bold text-sky-700 underline" onClick={openCategorySetup}>Add one in System Setup</button>.</p>}{errors.category&&<p className="form-error">{errors.category}</p>}</label>
          <label><span className="form-label">Service Name *</span><input className="form-control mt-1.5" maxLength={180} value={form.service_name} onChange={(e)=>update('service_name',e.target.value)} placeholder="e.g. Skin Scraping & KOH Examination" />{errors.service_name&&<p className="form-error">{errors.service_name}</p>}</label>
          <label className="rounded-2xl border-2 border-amber-300 bg-amber-50 p-4"><span className="text-sm font-black text-amber-900">Service Price *</span><input type="number" min="0.01" step="0.01" className="form-control mt-2 bg-white text-lg font-black" value={form.default_price} onChange={(e)=>update('default_price',e.target.value)} /><span className="mt-2 block text-xs text-amber-800">Base service amount before consumable prices are added.</span>{errors.default_price&&<p className="form-error">{errors.default_price}</p>}</label>
          <label><span className="form-label">Appointment Length *</span><select className="form-control mt-1.5" value={form.average_duration_minutes} onChange={(e)=>update('average_duration_minutes',Number(e.target.value))}>{editing && legacyDuration > 0 && !DURATION_OPTIONS.includes(legacyDuration) ? <option value={legacyDuration}>Existing: {formatDuration(legacyDuration)} — reserves {formatDuration(reservedDuration(legacyDuration))}</option> : null}{DURATION_OPTIONS.map((minutes)=><option key={minutes} value={minutes}>{formatDuration(minutes)}</option>)}</select><span className="form-helper">Time set aside: <strong>{formatDuration(reservedDuration(form.average_duration_minutes))}</strong>. Start times use 30-minute intervals.</span>{errors.average_duration_minutes&&<p className="form-error">{errors.average_duration_minutes}</p>}</label>
        </div>
        <div className="flex items-center justify-between gap-4 rounded-2xl bg-slate-50 p-4"><div><p className="text-sm font-bold text-slate-800">Service Availability</p><p className="mt-1 text-xs text-slate-500">{Number(form.is_active) === 1 ? 'Available for patient booking and doctor consultations.' : 'Unavailable for new bookings and consultation service selections.'}</p></div><button type="button" role="switch" aria-label="Service availability" aria-checked={Number(form.is_active) === 1} onClick={()=>update('is_active',Number(form.is_active)===1?0:1)} className={`relative h-7 w-12 shrink-0 rounded-full transition-colors ${Number(form.is_active)===1?'bg-emerald-500':'bg-slate-300'}`}><span className={`absolute left-5 top-1 h-5 w-5 rounded-full bg-white shadow transition-transform ${Number(form.is_active)===1?'translate-x-1':'-translate-x-4'}`} /></button></div>
      </div>}

      {step === 2 && <div className="space-y-4">
        <div className="flex items-start justify-between gap-4"><div><h2 className="text-lg font-black">Default Supplies</h2><p className="mt-1 text-sm text-slate-500">Choose inventory items normally used when this service is performed. Quantity Used is deducted from treatment-room stock only when the consultation is completed. Inventory quantities are tracked as whole units.</p></div><button className="button-secondary" onClick={()=>update('materials',[...form.materials,blankMaterial()])}><MdAdd /> Add Supply</button></div>
        {!form.materials.length ? <div className="rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-8 text-center text-sm text-slate-500">No default consumables.</div> : <div className="space-y-3">{form.materials.map((m,index)=>{const item=inventoryMap.get(Number(m.inventory_id)); const stepValue=1; const unitPrice=Number(item?.selling_price||0); const lineTotal=unitPrice*Math.max(0,Number(m.quantity||0)); return <div key={index} className="rounded-2xl border border-slate-200 p-4"><div className="flex justify-between"><strong className="text-xs uppercase tracking-wide text-slate-400">Consumable {index+1}</strong><button className="text-slate-400 hover:text-rose-600" onClick={()=>update('materials',form.materials.filter((_,i)=>i!==index))}><MdClose /></button></div><div className="mt-3 grid gap-3 sm:grid-cols-[1.4fr_.7fr_.9fr]"><label><span className="form-label">Inventory Item *</span><select className="form-control mt-1.5" value={m.inventory_id} onChange={(e)=>chooseInventory(index,e.target.value)}><option value="">Select item</option>{inventory.filter((inv)=>!inv.category||inv.category===form.clinic_type).map((inv)=><option key={inv.id} value={inv.id}>{inv.name} — {Number(inv.selling_price||0)>0?formatMoney(inv.selling_price):'Price not set'}</option>)}</select>{errors[`material_${index}`]&&<p className="form-error">{errors[`material_${index}`]}</p>}{errors[`price_${index}`]&&<p className="form-error">{errors[`price_${index}`]}</p>}</label><div><span className="form-label">Quantity Used *</span><input aria-label={`Quantity used for consumable ${index+1}`} type="number" min={stepValue} step={stepValue} className="form-control mt-1.5" value={m.quantity} onChange={(e)=>updateMaterial(index,'quantity',e.target.value)} /><p className="mt-1 text-[11px] text-slate-400">Whole units only.</p>{errors[`qty_${index}`]&&<p className="form-error">{errors[`qty_${index}`]}</p>}</div><div><span className="form-label">Consumable Price</span><div className="mt-1.5 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2.5 text-sm"><p className="font-bold text-slate-800">{unitPrice>0?formatMoney(unitPrice):'Not set'}</p><p className="mt-0.5 text-[11px] text-slate-400">{Number(m.quantity||0)>0&&unitPrice>0?`${formatMoney(lineTotal)} total`:'Inventory Selling Price'}</p></div></div><label className="sm:col-span-3"><span className="form-label">Notes</span><input maxLength={255} className="form-control mt-1.5" value={m.notes} onChange={(e)=>updateMaterial(index,'notes',e.target.value)} placeholder="Optional usage note" /></label></div></div>})}</div>}
        <div className="grid gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm sm:grid-cols-3"><div><p className="text-[10px] font-black uppercase tracking-wider text-amber-700">Service Price</p><p className="mt-1 font-black text-amber-950">{formatMoney(servicePrice)}</p></div><div><p className="text-[10px] font-black uppercase tracking-wider text-amber-700">Supplies Used</p><p className="mt-1 font-black text-amber-950">{formatMoney(consumablesTotal)}</p></div><div><p className="text-[10px] font-black uppercase tracking-wider text-amber-700">Total Patient Price</p><p className="mt-1 text-lg font-black text-amber-950">{formatMoney(patientPrice)}</p></div></div>
      </div>}

      {step === 3 && <div className="space-y-4"><div><h2 className="text-lg font-black">Review Service</h2><p className="mt-1 text-sm text-slate-500">Confirm the Service Price, consumable prices, and final patient price.</p></div><div className="rounded-2xl border border-slate-200 p-5"><h3 className="text-xl font-black">{form.service_name||'Unnamed Service'}</h3><p className="mt-1 text-sm text-slate-500">{form.category||'No category'} · {clinicLabel(form.clinic_type)} · {formatDuration(Number(form.average_duration_minutes || 60))} appointment length · {formatDuration(reservedDuration(form.average_duration_minutes))} reserved for booking · {Number(form.is_active)===1?'Active':'Inactive'}</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase text-slate-500">Service Price</p><p className="mt-2 text-xl font-black text-slate-900">{formatMoney(servicePrice)}</p></div><div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase text-slate-500">Supplies Used</p><p className="mt-2 text-xl font-black text-slate-900">{formatMoney(consumablesTotal)}</p></div><div className="rounded-2xl bg-amber-50 p-4"><p className="text-xs font-bold uppercase text-amber-700">Total Patient Price</p><p className="mt-2 text-2xl font-black text-amber-900">{formatMoney(patientPrice)}</p></div></div></div><div className="rounded-2xl border border-slate-200 p-5"><div className="flex items-center justify-between"><strong>Default Supplies</strong><span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold">{form.materials.length}</span></div>{form.materials.length?<div className="mt-3 divide-y divide-slate-100">{form.materials.map((m,index)=>{const item=inventoryMap.get(Number(m.inventory_id));const validItem=isInventoryCompatible(item);const unitPrice=validItem?Number(item?.selling_price||0):0;const lineTotal=unitPrice*Math.max(0,Number(m.quantity||0));return <div key={index} className="grid gap-1 py-3 text-sm sm:grid-cols-[1fr_auto]"><div><p className="font-semibold text-slate-800">{m.material_name||item?.name}</p><p className="text-xs text-slate-400">{m.quantity} unit{Number(m.quantity)===1?'':'s'} × {formatMoney(unitPrice)}</p></div><span className="font-bold text-slate-700">{formatMoney(lineTotal)}</span></div>})}</div>:<p className="mt-3 text-sm text-slate-500">No default consumables.</p>}</div><div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800"><MdCheck className="mr-1 inline" /> Total Patient Price = Service Price + Consumable Prices. Consumable stock is deducted when the consultation is completed.</div></div>}
    </section>

    <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-between"><div>{step===1?<button className="button-secondary" onClick={leaveEditor}><MdArrowBack /> Cancel</button>:<button className="button-secondary" disabled={saving} onClick={()=>move(step-1)}>Back</button>}</div><div>{step<3?<button className="button-primary min-w-32" onClick={()=>move(step+1)}>Continue</button>:<button className="button-primary min-w-40" disabled={saving} onClick={save}>{saving?'Saving…':editing?'Save Changes':'Add Service'}</button>}</div></div>
    <ConfirmDialog open={removeOpen} title={serviceUsageCount>0?'Deactivate service?':'Delete unused service?'} message={serviceUsageCount>0?'Deactivation removes this service from new appointments but keeps billing, appointment, and promotion history.':'This unused service will be permanently deleted. This cannot be undone.'} confirmLabel={serviceUsageCount>0?'Deactivate Service':'Delete Service'} loading={deleting} onCancel={()=>!deleting&&setRemoveOpen(false)} onConfirm={remove} />
  </div>
}

export default Admin_BillingServiceForm

import {useLocation} from 'react-router-dom'
import useClinicRefresh from '../../hooks/useClinicRefresh'
import { useCallback, useEffect, useRef, useState } from 'react'
import { MdAdd, MdCampaign, MdEdit, MdRefresh, MdCloudUpload, MdMap } from 'react-icons/md'
import { getAdminPromotions, saveAdminPromotion, getBillingCatalog, uploadPromotionImage, checkPromotionImage, } from '../../services/admin.service'
import { useToast } from '../../components/ui/ToastProvider'
import { getLocalDateOnly } from '../../utils/date'
import {promotionQuote,peso} from '../../utils/promotionPricing.mjs'
import VisibilitySwitch from '../../components/ui/VisibilitySwitch'

const newPromotion = () => ({
  title: '', description: '', badge_text: 'Special offer', starts_on: '', ends_on: '',
  is_active: true, show_on_dashboard: true, featured_order: 0, discount_type:'none',discount_value:0,
  image_url: '', image_token: '', clear_image: false, service_ids: [],
})

export default function Admin_Promotions({ onComposePost, onEmailOffer }) {
  const toast = useToast()
  const [promotions, setPromotions] = useState([])
  const [services, setServices] = useState([])
  const [loading, setLoading] = useState(true)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(newPromotion())
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [imageScan, setImageScan] = useState(null)
  const [filter, setFilter] = useState('')
  const [branchName, setBranchName] = useState('Your clinic branch')

  const load = async () => {
    setLoading(true)
    setError('')
    try {
      const [offers, catalog] = await Promise.all([getAdminPromotions(), getBillingCatalog({ includeInactive: true })])
      setPromotions(Array.isArray(offers) ? offers : [])
      setServices(Array.isArray(catalog) ? catalog : [])
      if (offers?.[0]?.branch_name) setBranchName(offers[0].branch_name)
    } catch (err) { setError(err.message || 'Unable to load promotions.') }
    finally { setLoading(false) }
  }
  useEffect(() => { void load() }, []) // eslint-disable-line react-hooks/exhaustive-deps
  useClinicRefresh(load, ['promotion.updated', 'service.updated'], { fallbackMs: 90000, skip: () => editing !== null })

  const open = useCallback((promo = null) => {
    setEditing(promo?.id || 'new')
    setError('')
    setImageScan(null)
    setFilter('')
    setForm(promo ? { ...newPromotion(), ...promo, image_token: '', clear_image: false, service_ids: promo.service_ids || [] } : newPromotion())
  },[])
  const notificationLocation=useLocation()
  const openedNotification=useRef(null)
  useEffect(()=>{
    const id=new URLSearchParams(notificationLocation.search).get('promotion_id')
    if(!id||loading||openedNotification.current===notificationLocation.key)return
    openedNotification.current=notificationLocation.key
    const promotion=promotions.find(p=>Number(p.id)===Number(id))
    if(promotion)open(promotion)
    else setError('This offer is no longer available in this branch.')
  },[loading,promotions,notificationLocation.search,notificationLocation.key,open])
  const update = (key, value) => setForm(current => ({ ...current, [key]: value }))
  const toggleService = (id, checked) => setForm(current => ({
    ...current, service_ids: checked ? [...current.service_ids, Number(id)] : current.service_ids.filter(value => Number(value) !== Number(id)),
  }))
  const save = async (event) => {
    event.preventDefault()
    if (form.ends_on < form.starts_on) return setError('End date must be on or after the start date.')
    if(form.discount_type!=='none' && (!form.service_ids.length || Number(form.discount_value)<=0 || (form.discount_type==='percentage'&&Number(form.discount_value)>100)))return setError('Select at least one service and enter a valid discount amount.')
    if (imageScan && imageScan.status !== 'approved') return setError('Please finish checking the photo or remove it before saving.')
    setSaving(true); setError('')
    try {
      await saveAdminPromotion(form, editing === 'new' ? null : editing)
      toast.success('Promotion saved.')
      setEditing(null)
      await load()
    } catch (err) { setError(err.message || 'Could not save promotion.') }
    finally { setSaving(false) }
  }
  const setVisibility = async (promo, visible) => {
    setSaving(true); setError('')
    try {
      await saveAdminPromotion({ ...promo, is_active: visible }, promo.id)
      toast.success(visible ? 'Promotion is visible.' : 'Promotion hidden.')
      await load()
    } catch (err) { setError(err.message || 'Could not update promotion visibility.') }
    finally { setSaving(false) }
  }
  const uploadImage = async file => {
    if (!file) return
    if (!['image/jpeg', 'image/png'].includes(file.type) || file.size > 5 * 1024 * 1024) {
      return setError('Choose a JPG or PNG photo under 5 MB.')
    }
    setSaving(true); setError('')
    try {
      const uploaded = await uploadPromotionImage(file)
      setForm(current => ({ ...current, image_url: uploaded.url, image_token: '', clear_image: false }))
      setImageScan({ status: 'pending', token: uploaded.scan_token })
    } catch (err) { setError(err.message || 'Photo upload failed.') }
    finally { setSaving(false) }
  }
  const verifyImage = async () => {
    if (!imageScan?.token) return
    setSaving(true); setError('')
    try {
      const result = await checkPromotionImage(imageScan.token)
      setImageScan(current => ({ ...current, status: result.status }))
      if (result.status === 'approved') {
        setForm(current => ({ ...current, image_url: result.url, image_token: result.security_token, clear_image: false }))
        toast.success('Photo ready.')
      } else setError('The photo is still being checked. Please try again, or remove it.')
    } catch (err) { setError(err.message || 'Could not check the photo.') }
    finally { setSaving(false) }
  }
  const today = getLocalDateOnly()
  return <div className="space-y-5">
    <header className="flex flex-wrap items-start justify-between gap-3 rounded-2xl border border-slate-200 bg-white p-5">
      <div>
        <h2 className="flex items-center gap-2 text-xl font-black text-slate-900"><MdCampaign className="text-amber-500" /> Promotions</h2>
        <p className="mt-1 text-sm text-slate-500">Create an offer once. It will appear on the website and in the patient dashboard during its dates.</p>
        <p className="mt-2 flex items-center gap-1 text-xs font-semibold text-slate-600"><MdMap /> {branchName}</p>
        <p className="mt-1 text-xs text-slate-500">Linked service discounts apply automatically when the booked service is billed.</p>
      </div>
      <div className="flex gap-2"><button type="button" onClick={load} className="button-secondary"><MdRefresh /> Refresh</button><button type="button" onClick={() => open()} className="button-primary"><MdAdd /> Add Promotion</button></div>
    </header>
    {error && <p role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}
    {editing !== null && <form onSubmit={save} className="space-y-4 rounded-2xl border border-emerald-200 bg-white p-5">
      <h3 className="text-lg font-black">{editing === 'new' ? 'Add Promotion' : 'Edit Promotion'}</h3>
      <p className="text-xs text-slate-500">This offer belongs to {branchName}. Patients will see the branch name.</p>
      <label className="block"><span className="form-label">Promotion Name *</span><input className="form-control mt-1" required maxLength={120} placeholder="Example: Skin Care Special" value={form.title} onChange={e => update('title', e.target.value)} /></label>
      <label className="block"><span className="form-label">Promotion Details *</span><textarea className="form-control mt-1" required rows={3} maxLength={1000} value={form.description} onChange={e => update('description', e.target.value)} placeholder="What is the offer and who can use it?" /></label>
      <div className="grid gap-3 sm:grid-cols-2">
        <label><span className="form-label">Start Date *</span><input className="form-control mt-1" type="date" required value={form.starts_on} onChange={e => update('starts_on', e.target.value)} /></label>
        <label><span className="form-label">End Date *</span><input className="form-control mt-1" type="date" required min={form.starts_on || undefined} value={form.ends_on} onChange={e => update('ends_on', e.target.value)} /></label>
      </div>
      <div className="space-y-2 rounded-xl border border-dashed border-slate-300 p-4">
        <p className="form-label">Promotion Photo (Optional)</p>
        <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg bg-slate-100 px-3 py-2 text-sm font-bold"><MdCloudUpload /> Choose Photo<input className="sr-only" type="file" accept="image/jpeg,image/png" disabled={saving} onChange={e => { void uploadImage(e.target.files?.[0]); e.target.value = '' }} /></label>
        {form.image_url && <img alt="Promotion" src={form.image_url} className="max-h-48 w-full rounded-xl object-cover" />}
        {imageScan?.status === 'pending' && <button type="button" className="button-secondary" disabled={saving} onClick={verifyImage}>Finish Checking Photo</button>}
        {imageScan?.status === 'approved' && <p className="text-xs font-bold text-emerald-700">Photo is ready.</p>}
        {form.image_url && <button type="button" className="block text-xs font-bold text-rose-700 underline" onClick={() => { setImageScan(null); setForm(current => ({ ...current, image_url: '', image_token: '', clear_image: true })) }}>Remove Photo</button>}
      </div>
      <div className="grid gap-3 rounded-xl border border-emerald-100 bg-emerald-50/40 p-4 sm:grid-cols-2">
        <label className="form-label">Discount type
          <select className="form-control mt-1" value={form.discount_type} onChange={e=>setForm(s=>({...s,discount_type:e.target.value,discount_value:e.target.value==='none'?0:s.discount_value}))}>
            <option value="none">Informational offer (no price change)</option>
            <option value="percentage">Percentage (%)</option>
            <option value="fixed">Fixed amount (₱)</option>
          </select>
        </label>
        {form.discount_type!=='none' && <label className="form-label">{form.discount_type==='percentage'?'Discount percentage':'Discount amount (₱)'}
          <input className="form-control mt-1" type="number" required min="0.01" max={form.discount_type==='percentage'?100:99999999.99} step="0.01" value={form.discount_value} onChange={e=>update('discount_value',e.target.value)}/>
        </label>}
        <p className="text-xs text-slate-600 sm:col-span-2">Discounts apply only to eligible services. They do not change the service catalog's original price.</p>
      </div>
      <div className="rounded-xl border border-slate-200 px-3 py-2">
        <VisibilitySwitch checked={Boolean(form.is_active)} onChange={visible=>update('is_active',visible)} label="Show promotion" disabled={saving} />
        <p className="pl-2 text-xs text-slate-500">Patients who opted in and previously visited this branch receive one in-app alert when this offer goes live. No SMS or email is sent.</p>
      </div>
      <details className="rounded-xl border border-slate-200 p-3">
        <summary className="cursor-pointer text-sm font-bold">Eligible Services {form.discount_type==='none'?'(Optional)':'*'}</summary>
        <p className="mt-2 text-xs text-slate-500">Choose the services this offer applies to. Discounted offers require at least one service.</p>
        <input className="form-control mt-3" value={filter} onChange={e => setFilter(e.target.value)} placeholder="Find a service" />
        <div className="mt-2 grid max-h-48 gap-1 overflow-auto sm:grid-cols-2">{services.filter(service => Number(service.is_active) !== 0 && `${service.service_name} ${service.clinic_type}`.toLowerCase().includes(filter.toLowerCase())).map(service => <label key={service.id} className="flex cursor-pointer items-center gap-2 rounded-lg p-2 text-xs hover:bg-slate-50"><input type="checkbox" checked={form.service_ids.some(id => Number(id) === Number(service.id))} onChange={e => toggleService(service.id, e.target.checked)} />{service.service_name}</label>)}</div>
      </details>
      {form.discount_type!=='none' && form.service_ids.length>0 && <div className="rounded-xl bg-slate-50 p-4 text-sm">
        <p className="mb-2 font-bold text-slate-800">Patient price preview</p>
        {services.filter(service=>form.service_ids.some(id=>Number(id)===Number(service.id))).slice(0,5).map(service=>{
          const quote=promotionQuote(service.default_price,form)
          return <div className="flex flex-wrap justify-between gap-2 py-1" key={service.id}><span>{service.service_name}</span><span>{quote ? <><s className="text-slate-500">{peso(quote.original)}</s> <strong className="text-emerald-700">{peso(quote.current)}</strong></> : 'Price unavailable'}</span></div>
        })}
      </div>}
      <div className="flex justify-end gap-2"><button type="button" className="button-secondary" disabled={saving} onClick={() => { setEditing(null); setError('') }}>Cancel</button><button type="submit" className="button-primary" disabled={saving}>{saving ? 'Saving…' : 'Save Promotion'}</button></div>
    </form>}
    {loading ? <p className="text-sm text-slate-500">Loading promotions…</p> : !promotions.length ? <div className="rounded-xl border border-dashed bg-white p-8 text-center text-sm text-slate-500">No promotions yet. Select Add Promotion to create one.</div> : <div className="grid gap-3">
      {promotions.map(promo => {
        const live = promo.is_active && promo.starts_on <= today && promo.ends_on >= today
        return <article key={promo.id} className="overflow-hidden rounded-2xl border border-slate-200 bg-white sm:flex">
          {promo.image_url && <img alt="" src={promo.image_url} loading="lazy" className="h-44 w-full object-cover sm:h-auto sm:w-48" />}
          <div className="min-w-0 flex-1 p-4"><div className="flex flex-wrap items-start justify-between gap-3">
            <div><div className="flex items-center gap-2"><h3 className="font-bold">{promo.title}</h3><span className={`rounded-full px-2 py-0.5 text-xs ${live ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}>{live ? 'Showing' : !promo.is_active ? 'Hidden' : promo.starts_on > today ? 'Upcoming' : 'Ended'}</span></div>
              <p className="mt-1 text-sm text-slate-600">{promo.description}</p><p className="mt-2 text-xs text-slate-500">{promo.branch_name || branchName} · {promo.starts_on} to {promo.ends_on}{promo.service_ids?.length ? ` · ${promo.service_ids.length} selected service(s)` : ' · General offer'}{promo.discount_type==='percentage'?` · ${promo.discount_value}% off`:promo.discount_type==='fixed'?` · ₱${Number(promo.discount_value).toFixed(2)} off`:''}</p>
            </div><div className="flex flex-wrap gap-2">
              {onComposePost && <button type="button" className="button-secondary" onClick={()=>onComposePost(promo)}>Create Promo Post</button>}
              {onEmailOffer && <button type="button" className="button-secondary" onClick={()=>onEmailOffer(promo)}>Email Patients</button>}<button type="button" className="button-secondary" onClick={() => open(promo)}><MdEdit /> Edit</button><VisibilitySwitch checked={Boolean(promo.is_active)} onChange={visible=>setVisibility(promo,visible)} label="Show promotion" disabled={saving} /></div>
          </div></div>
        </article>
      })}
    </div>}
  </div>
}

import useClinicRefresh from '../../hooks/useClinicRefresh'
import { useEffect, useMemo, useRef, useState } from 'react'
import {
  MdAssessment,
  MdCalendarToday,
  MdChecklist,
  MdGroups,
  MdInventory2,
  MdMedication,
  MdPayments,
  MdPictureAsPdf,
  MdRefresh,
  MdTrendingUp,
  MdWarningAmber,
} from 'react-icons/md'
import { doctorClinicLabel } from '../../utils/doctor'
import { getReports, recordReportExport } from '../../services/admin.service'
import { useToast } from '../../components/ui/ToastProvider'
import { ErrorState, LoadingState } from '../../components/ui/PageState'
import { ComboChart, GroupedColumnChart, HorizontalBarChart, LineChart } from '../../components/charts/AnalyticsCharts'

const formatMoney = (value) => new Intl.NumberFormat('en-PH', {
  style: 'currency',
  currency: 'PHP',
  maximumFractionDigits: 2,
}).format(Number(value) || 0)

const formatPercent = (value) => `${Math.round(Number(value) || 0)}%`
const REPORT_RANGE_OPTIONS = [
  ['today', 'Today'],
  ['7days', '7 Days'],
  ['30days', '30 Days'],
  ['3months', '3 Months'],
  ['6months', '6 Months'],
  ['year', 'This Year'],
  ['custom', 'Custom'],
]
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;')

const toDateInput = (date) => {
  const value = date instanceof Date ? date : new Date(date)
  const year = value.getFullYear()
  const month = String(value.getMonth() + 1).padStart(2, '0')
  const day = String(value.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

const getPresetRange = (preset) => {
  const end = new Date()
  const start = new Date(end)
  if (preset === 'today') return { startDate: toDateInput(end), endDate: toDateInput(end) }
  if (preset === '7days') start.setDate(start.getDate() - 6)
  else if (preset === '30days') start.setDate(start.getDate() - 29)
  else if (preset === '3months') start.setMonth(start.getMonth() - 3)
  else if (preset === 'year') start.setMonth(0, 1)
  else start.setMonth(start.getMonth() - 6)
  return { startDate: toDateInput(start), endDate: toDateInput(end) }
}

const formatRangeLabel = (range) => {
  if (!range?.start_date || !range?.end_date) return 'Selected period'
  const format = (value) => new Date(`${value}T00:00:00`).toLocaleDateString('en-PH', {
    month: 'short', day: 'numeric', year: 'numeric',
  })
  return `${format(range.start_date)} – ${format(range.end_date)}`
}

const titleCase = (value) => String(value || '')
  .replace(/[_-]/g, ' ')
  .replace(/\b\w/g, (char) => char.toUpperCase())

const inventoryMovementLabel = (value) => ({
  adjustment_out: 'Manual Stock Out',
  received: 'Received from Supplier',
  returned: 'Returned to Stock',
  correction_in: 'Inventory Correction (+)',
  clinical_use: 'Clinical Use',
  dispensing: 'Dispensing',
  dispensed: 'Dispensed at Checkout',
  clinical_return: 'Unused Consumable Returned',
  dispense_return: 'Checkout Medicine Returned',
  wastage: 'Wastage / Spillage',
  expired: 'Expired Stock',
  damaged: 'Damaged Stock',
  returned_to_supplier: 'Returned to Supplier',
  transfer_out: 'Stock Transfer Out',
  transfer_in: 'Stock Transfer In',
}[String(value || '').toLowerCase()] || titleCase(value))

const StatCard = ({ label, value, helper, icon: Icon, tone = 'border-slate-200 bg-white text-slate-900' }) => (
