const formatQty = (value) => {
  const number = Number(value) || 0
  return Number.isInteger(number) ? number.toLocaleString('en-PH') : number.toLocaleString('en-PH', { maximumFractionDigits: 2 })
}

const MostUsedTable = ({ rows, kindLabel }) => {
