        <tbody className="divide-y divide-slate-100">
          {rows.map((row, index) => (
            <tr key={row.inventory_id} className={index === 0 ? 'bg-emerald-50/60' : ''}>
              <td className="px-3 py-3 font-black text-slate-400">{index + 1}</td>
