const Admin_Reports = () => {
  const toast = useToast()
  const [usageKind, setUsageKind] = useState('medicine')
  const initialRange = getPresetRange('6months')
  const [preset, setPreset] = useState('6months')
  const [dateRange, setDateRange] = useState(initialRange)
  const [appliedRange, setAppliedRange] = useState(initialRange)
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const activeReportRequest = useRef(null)

  const load = async () => {
    // React Strict Mode and rapid date changes must not produce duplicate toasts
    // or allow an old request to overwrite a newer report.
    activeReportRequest.current?.abort()
    const controller = new AbortController()
    activeReportRequest.current = controller
    setLoading(true)
    setError('')
    try {
      const nextData = await getReports(appliedRange, { signal: controller.signal })
      if (!controller.signal.aborted) setData(nextData)
    } catch (err) {
      if (controller.signal.aborted || err?.name === 'AbortError') return
      const message = err?.message || 'Unable to load reports right now. Please try again.'
      console.error('Reports load error:', err)
      setError(message)
      toast.error(message)
    } finally {
      if (!controller.signal.aborted) setLoading(false)
      if (activeReportRequest.current === controller) activeReportRequest.current = null
    }
  }

  useEffect(() => {
    load()
    return () => activeReportRequest.current?.abort()
  }, [appliedRange.startDate, appliedRange.endDate])

  useClinicRefresh(load,['billing.updated','appointment.updated','inventory.updated'],{fallbackMs:0})

  const applyPreset = (nextPreset) => {
    if (nextPreset === 'custom') {
      setPreset('custom')
      return
    }
    const next = getPresetRange(nextPreset)
    setPreset(nextPreset)
    setDateRange(next)
    setAppliedRange(next)
  }

  const applyCustomRange = () => {
    if (!dateRange.startDate || !dateRange.endDate) return toast.warning('Select a start and end date.')
    if (dateRange.startDate > dateRange.endDate) return toast.warning('Start date cannot be after end date.')
    setPreset('custom')
    setAppliedRange({ ...dateRange })
  }

  const report = useMemo(() => {
    const appointmentSummary = data?.appointmentSummary || {}
    const billing = data?.billingSummary || {}
    const inventory = data?.inventoryStats || {}
    const current = data?.currentOperations || {}
    const monthly = Array.isArray(data?.monthly) ? data.monthly : []
    const revenueTrend = Array.isArray(data?.revenueTrend) ? data.revenueTrend : []
    const status = Array.isArray(data?.statusBreakdown) ? data.statusBreakdown : []
    const sources = Array.isArray(data?.appointmentSources) ? data.appointmentSources : []
    const doctors = Array.isArray(data?.topDoctors) ? data.topDoctors : []
    const payments = Array.isArray(data?.paymentsByMethod) ? data.paymentsByMethod : []
    const services = Array.isArray(data?.serviceRevenue) ? data.serviceRevenue : []
    const stockActivity = Array.isArray(data?.stockActivity) ? data.stockActivity : []
    const stockReasons = Array.isArray(data?.stockMovementByReason) ? data.stockMovementByReason : []
    const categories = Array.isArray(data?.inventoryByCategory) ? data.inventoryByCategory : []
    const mostUsedMedicines = Array.isArray(data?.mostUsedMedicines) ? data.mostUsedMedicines : []
    const mostUsedSupplies = Array.isArray(data?.mostUsedSupplies) ? data.mostUsedSupplies : []

    const totalAppointments = Number(appointmentSummary.appointments || 0)
    const completed = Number(appointmentSummary.completed || 0)
    const cancelled = Number(appointmentSummary.cancelled || 0)
    const noShow = Number(appointmentSummary.no_show || 0)
    const completionRate = totalAppointments ? (completed / totalAppointments) * 100 : 0
    const revenueByMonth = new Map(revenueTrend.map((row) => [row.ym, Number(row.revenue || 0)]))
    const appointmentsByMonth = new Map(monthly.map((row) => [row.ym, Number(row.appointments || 0)]))
    const monthLabels = new Map([...monthly, ...revenueTrend].map((row) => [row.ym, row.month]))
    const performanceTrend = Array.from(new Set([...appointmentsByMonth.keys(), ...revenueByMonth.keys()]))
      .sort()
      .map((ym) => ({ ym, month: monthLabels.get(ym) || ym, appointments: appointmentsByMonth.get(ym) || 0, revenue: revenueByMonth.get(ym) || 0 }))

    return {
      appointmentSummary, billing, inventory, current, monthly, revenueTrend, status, sources,
      doctors, payments, services, stockActivity, stockReasons, categories, mostUsedMedicines, mostUsedSupplies,
      totalAppointments, completed, cancelled, noShow, completionRate, performanceTrend,
    }
  }, [data])

  const rangeLabel = formatRangeLabel(data?.range)

  const handleExportPdf = () => {
    if (!data) return
    recordReportExport({ start_date: data?.range?.start_date, end_date: data?.range?.end_date }).catch(() => {})
    const clinic = data.clinicSettings || {}
    const generatedAt = new Date().toLocaleString('en-PH')
    const doctorRows = report.doctors.map((doctor) => {
      const completion = Number(doctor.appointments || 0)
        ? Math.round((Number(doctor.completed || 0) / Number(doctor.appointments || 1)) * 100)
        : 0
      return `<tr><td>${escapeHtml(doctor.name)}</td><td>${escapeHtml(doctorClinicLabel(doctor))}</td><td>${escapeHtml(doctor.appointments || 0)}</td><td>${escapeHtml(doctor.patients || 0)}</td><td>${escapeHtml(doctor.completed || 0)}</td><td>${completion}%</td></tr>`
    }).join('')
    const serviceRows = report.services.map((row) => `<tr><td>${escapeHtml(row.service_name)}</td><td>${escapeHtml(row.bills)}</td><td>${escapeHtml(row.quantity)}</td><td>${escapeHtml(formatMoney(row.gross_billed_amount))}</td></tr>`).join('')
    const paymentRows = report.payments.map((row) => `<tr><td>${escapeHtml(titleCase(row.payment_method))}</td><td>${escapeHtml(row.transactions)}</td><td>${escapeHtml(formatMoney(row.amount))}</td></tr>`).join('')
    const sourceRows = report.sources.map((row) => `<tr><td>${escapeHtml(titleCase(row.source))}</td><td>${escapeHtml(row.value)}</td></tr>`).join('')
    const inventoryRows = report.stockReasons.map((row) => `<tr><td>${escapeHtml(inventoryMovementLabel(row.movement_type))}</td><td>${escapeHtml(row.actions)}</td><td>${escapeHtml(row.quantity)}</td></tr>`).join('')
    const monthlyRows = report.monthly.map((row) => `<tr><td>${escapeHtml(row.month)}</td><td>${escapeHtml(row.appointments)}</td><td>${escapeHtml(row.medical || 0)}</td><td>${escapeHtml(row.derma || 0)}</td><td>${escapeHtml(row.patients)}</td></tr>`).join('')
    const usageRows = (rows) => rows.map((row, index) => `<tr><td>${index + 1}</td><td>${escapeHtml(row.name)}</td><td>${escapeHtml(formatQty(row.total_used))} ${escapeHtml(row.unit)}</td><td>${escapeHtml(formatQty(row.used_in_consultation))}</td><td>${escapeHtml(formatQty(row.dispensed_at_checkout))}</td><td>${escapeHtml(row.visits)}</td><td>${escapeHtml(formatMoney(row.billed_amount))}</td></tr>`).join('')
    const medicineRows = usageRows(report.mostUsedMedicines)
    const supplyRows = usageRows(report.mostUsedSupplies)
    const revenueRows = report.revenueTrend.map((row) => `<tr><td>${escapeHtml(row.month)}</td><td>${escapeHtml(row.transactions)}</td><td>${escapeHtml(formatMoney(row.revenue))}</td></tr>`).join('')

    const html = `<!doctype html><html><head><meta charset="utf-8"><title>Clinic Report</title><style>
      @page { size: A4; margin: 13mm 12mm 17mm; }
      * { box-sizing: border-box; }
      body { font-family: Arial, sans-serif; margin: 0; color: #0f172a; font-size: 10.5px; padding-bottom: 12mm; }
      header { border-bottom: 2px solid #0f172a; padding-bottom: 10px; margin-bottom: 12px; }
      h1 { margin: 0; font-size: 18px; text-transform: uppercase; } h2 { margin: 16px 0 7px; font-size: 12px; page-break-after: avoid; }
      p { margin: 3px 0; color: #475569; } .meta { display:flex; justify-content:space-between; gap:12px; }
      .cards { display:grid; grid-template-columns:repeat(4,1fr); gap:6px; margin:10px 0; }
      .card { border:1px solid #cbd5e1; border-radius:7px; padding:7px; } .label { font-size:7.5px; text-transform:uppercase; color:#64748b; }
      .value { margin-top:4px; font-size:13px; font-weight:700; } table { width:100%; border-collapse:collapse; margin-top:5px; page-break-inside:auto; }
      thead { display:table-header-group; } tr { page-break-inside:avoid; } th,td { border:1px solid #cbd5e1; padding:5px; vertical-align:top; }
      th { background:#f1f5f9; font-size:8px; text-transform:uppercase; text-align:left; } .note { background:#f8fafc; border:1px solid #e2e8f0; padding:7px; border-radius:7px; }
      footer { position:fixed; bottom:-11mm; left:0; right:0; text-align:center; color:#64748b; font-size:7.5px; }
    </style></head><body>
      <header><h1>${escapeHtml(clinic.clinic_name || 'CARAIT MEDICAL AND DERMATOLOGY CLINIC')}</h1><p>${escapeHtml(clinic.address || '')}</p><div class="meta"><p><strong>Reports & Analytics</strong><br>Period: ${escapeHtml(rangeLabel)}</p><p>Generated: ${escapeHtml(generatedAt)}<br>Generated by: Administrator</p></div></header>
      <h2>1. Executive Summary</h2><div class="cards">
        <div class="card"><div class="label">Appointments</div><div class="value">${report.totalAppointments}</div></div>
        <div class="card"><div class="label">Unique Patients</div><div class="value">${Number(report.appointmentSummary.unique_patients || 0)}</div></div>
        <div class="card"><div class="label">Net Collections</div><div class="value">${escapeHtml(formatMoney(report.billing.net_collected))}</div></div>
        <div class="card"><div class="label">Outstanding Now</div><div class="value">${escapeHtml(formatMoney(report.billing.outstanding))}</div></div>
      </div>
      <h2>2. Financial Summary</h2><table><tbody>
        <tr><th>Gross Billed</th><td>${escapeHtml(formatMoney(report.billing.gross_billed))}</td><th>Discounts</th><td>${escapeHtml(formatMoney(report.billing.discounts))}</td></tr>
        <tr><th>Net Billed</th><td>${escapeHtml(formatMoney(report.billing.net_billed))}</td><th>Collections</th><td>${escapeHtml(formatMoney(report.billing.collected))}</td></tr>
        <tr><th>Refunded</th><td>${escapeHtml(formatMoney(report.billing.refunded))}</td><th>Net Collections</th><td>${escapeHtml(formatMoney(report.billing.net_collected))}</td></tr>
        <tr><th>Voided Payments</th><td>${escapeHtml(formatMoney(report.billing.voided_payments))}</td><th>Gross Received</th><td>${escapeHtml(formatMoney(report.billing.gross_received))}</td></tr>
        <tr><th>Outstanding Now</th><td>${escapeHtml(formatMoney(report.billing.outstanding))}</td><th>Voided Bills</th><td>${escapeHtml(report.billing.voided_bills || 0)}</td></tr>
      </tbody></table>
      <h2>3. Collection Trend</h2><table><thead><tr><th>Month</th><th>Transactions</th><th>Net Collection</th></tr></thead><tbody>${revenueRows || '<tr><td colspan="3">No collections.</td></tr>'}</tbody></table>
      <h2>4. Appointment Summary</h2><table><thead><tr><th>Month</th><th>Appointments</th><th>Medical</th><th>Dermatology</th><th>Patients</th></tr></thead><tbody>${monthlyRows || '<tr><td colspan="5">No appointments.</td></tr>'}</tbody></table>
      <h2>Appointment Source</h2><table><thead><tr><th>Source</th><th>Visits</th></tr></thead><tbody>${sourceRows || '<tr><td colspan="2">No data.</td></tr>'}</tbody></table>
      <h2>5. Doctor Activity</h2><table><thead><tr><th>Doctor</th><th>Clinic Assignment</th><th>Appointments</th><th>Unique Patients</th><th>Completed</th><th>Completion</th></tr></thead><tbody>${doctorRows || '<tr><td colspan="6">No doctor activity.</td></tr>'}</tbody></table>
      <h2>6. Billing Detail</h2><table><thead><tr><th>Payment Method</th><th>Transactions</th><th>Collected</th></tr></thead><tbody>${paymentRows || '<tr><td colspan="3">No payments.</td></tr>'}</tbody></table>
      <h2>Top Services by Gross Billed Amount</h2><table><thead><tr><th>Service</th><th>Bills</th><th>Qty</th><th>Gross Billed</th></tr></thead><tbody>${serviceRows || '<tr><td colspan="4">No billed services.</td></tr>'}</tbody></table>
      <h2>7. Most Used Medicines</h2><table><thead><tr><th>#</th><th>Medicine</th><th>Total Used</th><th>In Consultations</th><th>Dispensed at Checkout</th><th>Visits</th><th>Billed</th></tr></thead><tbody>${medicineRows || '<tr><td colspan="7">No medicines used in this period.</td></tr>'}</tbody></table>
      <h2>Most Used Supplies</h2><table><thead><tr><th>#</th><th>Supply</th><th>Total Used</th><th>In Consultations</th><th>Dispensed at Checkout</th><th>Visits</th><th>Billed</th></tr></thead><tbody>${supplyRows || '<tr><td colspan="7">No supplies used in this period.</td></tr>'}</tbody></table>
      <h2>8. Inventory Movement</h2><table><thead><tr><th>Movement</th><th>Actions</th><th>Quantity</th></tr></thead><tbody>${inventoryRows || '<tr><td colspan="3">No stock movement.</td></tr>'}</tbody></table>
      <p class="note"><strong>Current inventory snapshot:</strong> ${report.inventory.total_items || 0} items · value at cost ${escapeHtml(formatMoney(report.inventory.cost_value))} · value at selling price ${escapeHtml(formatMoney(report.inventory.retail_value))} · ${report.inventory.out_of_stock || 0} out of stock · ${report.inventory.low_stock || 0} low stock · ${report.inventory.expired || 0} expired · ${report.inventory.expiring_soon || 0} expiring within 30 days. Current values are not historical balances for the selected period.</p>
      <footer>${escapeHtml(clinic.report_footer || clinic.clinic_name || 'CARAIT MEDICAL AND DERMATOLOGY CLINIC')} · ${escapeHtml(rangeLabel)}</footer>
    </body></html>`

    const frame = document.createElement('iframe')
    frame.title = 'Printable clinic report'
    frame.style.cssText = 'position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;left:-9999px;'
    document.body.appendChild(frame)
    const cleanup = () => { if (frame.parentNode) frame.remove() }
    frame.onload = () => {
      const win = frame.contentWindow
      if (!win) return cleanup()
      win.addEventListener('afterprint', cleanup, { once: true })
      win.focus()
      win.print()
      window.setTimeout(cleanup, 10000)
    }
    frame.srcdoc = html
    toast.info('Print dialog opened. Choose “Save as PDF” to save the report.')
  }

  if (loading) return <LoadingState label="Loading reports and analytics..." />
  if (error) return <ErrorState message={error} onRetry={load} />

  return (
    <div className="mx-auto w-full max-w-7xl space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="flex items-center gap-2 text-2xl font-bold text-slate-900"><MdAssessment className="text-sky-500" /> Reports & Analytics</h1>
          <p className="mt-1 text-sm text-slate-500">Financial and clinic activity for the selected period, with a separate current operational snapshot.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={load} className="button-secondary"><MdRefresh /> Refresh</button>
          <button onClick={handleExportPdf} className="button-secondary"><MdPictureAsPdf className="text-rose-500" /> Print / Save PDF</button>
        </div>
      </div>

      <section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
        <div className="grid gap-3 sm:grid-cols-[220px_1fr_1fr_auto] sm:items-end">
          <label>
            <span className="form-label">Date Range</span>
            <select className="form-control mt-1.5" value={preset} onChange={(e) => applyPreset(e.target.value)}>
              {REPORT_RANGE_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}
            </select>
          </label>
          <label><span className="form-label">Start Date</span><input type="date" disabled={preset !== 'custom'} className="form-control mt-1.5 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500" value={dateRange.startDate} onChange={(e) => setDateRange((current) => ({ ...current, startDate: e.target.value }))} /></label>
          <label><span className="form-label">End Date</span><input type="date" disabled={preset !== 'custom'} className="form-control mt-1.5 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500" value={dateRange.endDate} onChange={(e) => setDateRange((current) => ({ ...current, endDate: e.target.value }))} /></label>
          <button onClick={applyCustomRange} disabled={preset !== 'custom'} className="button-primary disabled:cursor-not-allowed disabled:opacity-50">Apply Range</button>
        </div>
        <p className="mt-3 text-xs font-semibold text-slate-500">Selected period: {rangeLabel}</p>
      </section>

      <div>
        <p className="mb-3 text-xs font-black uppercase tracking-[0.2em] text-slate-400">Selected Period · Financial</p>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <StatCard label="Gross Billed" value={formatMoney(report.billing.gross_billed)} helper={`${report.billing.paid_bills || 0} paid · ${report.billing.partially_paid_bills || 0} partial`} icon={MdPayments} tone="border-sky-200 bg-sky-50 text-sky-800" />
          <StatCard label="Net Billed" value={formatMoney(report.billing.net_billed)} helper={`${formatMoney(report.billing.discounts)} discounts`} icon={MdChecklist} tone="border-violet-200 bg-violet-50 text-violet-800" />
          <StatCard label="Net Collections" value={formatMoney(report.billing.net_collected)} helper={`${formatMoney(report.billing.refunded)} refunded · ${formatMoney(report.billing.voided_payments)} voided`} icon={MdTrendingUp} tone="border-emerald-200 bg-emerald-50 text-emerald-800" />
          <StatCard label="Outstanding Now" value={formatMoney(report.billing.outstanding)} helper="Current unpaid balance across open bills" icon={MdWarningAmber} tone="border-amber-200 bg-amber-50 text-amber-800" />
        </div>
      </div>

      <Section title="Collection Trend" subtitle="Net collections by month. Each payment, void and refund is counted on the day it happened, so closed months do not change later.">
        <LineChart
          data={report.revenueTrend}
          xKey="month"
          yKey="revenue"
          valueFormatter={(value) => new Intl.NumberFormat('en-PH', { notation: 'compact', maximumFractionDigits: 1 }).format(Number(value) || 0)}
          emptyMessage="No collection data for this period."
        />
      </Section>

      <Section title="Clinic Performance" subtitle="Appointments are shown as columns while net collections are shown as a line, making volume and revenue easier to compare.">
        <ComboChart
          data={report.performanceTrend}
          xKey="month"
          columnKey="appointments"
          lineKey="revenue"
          columnLabel="Appointments"
          lineLabel="Net Collections"
          lineFormatter={(value) => new Intl.NumberFormat('en-PH', { notation: 'compact', maximumFractionDigits: 1 }).format(Number(value) || 0)}
          emptyMessage="No appointment or collection data for this period."
        />
      </Section>

      <div>
        <p className="mb-3 text-xs font-black uppercase tracking-[0.2em] text-slate-400">Selected Period · Clinic Operations</p>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <StatCard label="Appointments" value={report.totalAppointments} helper={`${report.appointmentSummary.unique_patients || 0} unique patients`} icon={MdCalendarToday} />
          <StatCard label="Completion Rate" value={formatPercent(report.completionRate)} helper={`${report.completed} completed`} icon={MdChecklist} />
          <StatCard label="Cancelled / No-show" value={report.cancelled + report.noShow} helper={`${report.cancelled} cancelled · ${report.noShow} no-show`} icon={MdWarningAmber} />
          <StatCard label="Patient Mix" value={`${report.appointmentSummary.new_patients || 0} new`} helper={`${report.appointmentSummary.returning_patients || 0} returning`} icon={MdGroups} />
        </div>
      </div>

      <div className="grid gap-5 xl:grid-cols-2">
        <Section title="Monthly Appointments" subtitle="Grouped columns compare General Medicine and Dermatology visits.">
          <GroupedColumnChart
            data={report.monthly}
            xKey="month"
            series={[
              { key: 'medical', label: 'General Medicine', badgeClass: 'bg-sky-500', textClass: 'text-sky-500' },
              { key: 'derma', label: 'Dermatology', badgeClass: 'bg-emerald-500', textClass: 'text-emerald-500' },
            ]}
            emptyMessage="No appointment data for this period."
          />
        </Section>

        <Section title="Appointment Source" subtitle="Where each visit originated.">
          <div className="space-y-3">
            {report.sources.length === 0 ? <p className="py-8 text-center text-sm text-slate-400">No source data.</p> : report.sources.map((row) => (
              <div key={row.source} className="flex items-center justify-between rounded-2xl bg-slate-50 px-4 py-3">
                <span className="text-sm font-semibold text-slate-700">{titleCase(row.source)}</span>
                <span className="text-lg font-black text-slate-900">{row.value}</span>
              </div>
            ))}
          </div>
        </Section>
      </div>

      <Section title="Doctor Activity" subtitle="Completion rate is completed appointments ÷ all appointments for that doctor.">
        <div className="overflow-x-auto">
          <table className="min-w-full text-left text-sm">
            <thead className="border-b border-slate-200 text-[10px] uppercase tracking-widest text-slate-400"><tr><th className="px-3 py-3">Doctor</th><th className="px-3 py-3">Clinic Assignment</th><th className="px-3 py-3 text-right">Appointments</th><th className="px-3 py-3 text-right">Patients</th><th className="px-3 py-3 text-right">Completed</th><th className="px-3 py-3 text-right">Completion</th></tr></thead>
            <tbody className="divide-y divide-slate-100">{report.doctors.map((doctor) => {
              const rate = Number(doctor.appointments || 0) ? (Number(doctor.completed || 0) / Number(doctor.appointments || 1)) * 100 : 0
              return <tr key={doctor.name}><td className="px-3 py-3 font-bold text-slate-800">{doctor.name}</td><td className="px-3 py-3 text-slate-500">{doctorClinicLabel(doctor)}</td><td className="px-3 py-3 text-right">{doctor.appointments}</td><td className="px-3 py-3 text-right">{doctor.patients}</td><td className="px-3 py-3 text-right">{doctor.completed}</td><td className="px-3 py-3 text-right font-bold">{formatPercent(rate)}</td></tr>
            })}</tbody>
          </table>
        </div>
      </Section>

      <div className="grid gap-5 xl:grid-cols-2">
        <Section title="Payments by Method" subtitle="Payments received minus voids and refunds recorded in the selected period.">
          <HorizontalBarChart
            data={report.payments.map((row) => ({ label: `${titleCase(row.payment_method)} · ${row.transactions} tx`, value: Number(row.amount) || 0 }))}
            valueFormatter={formatMoney}
            emptyMessage="No payments for this period."
          />
        </Section>
        <Section title="Top Services by Gross Billed Amount" subtitle="Before bill-level discounts; historical bill price snapshots are preserved.">
          <HorizontalBarChart
            data={report.services.slice(0, 8).map((row) => ({ label: row.service_name, value: Number(row.gross_billed_amount) || 0 }))}
            valueFormatter={formatMoney}
            emptyMessage="No billed services for this period."
          />
        </Section>
      </div>

      <Section
        title={usageKind === 'medicine' ? 'Most Used Medicines' : 'Most Used Supplies'}
        subtitle="Ranked by quantity that left stock for patients in the selected period: used during consultations plus dispensed at Checkout, minus anything returned. Visits counts consultations and paid bills."
        action={(
          <div className="flex rounded-xl border border-slate-200 bg-slate-50 p-1" role="tablist" aria-label="Item type">
            {[['medicine', 'Medicines'], ['supplies', 'Supplies']].map(([value, label]) => (
              <button
                key={value}
                type="button"
                role="tab"
                aria-selected={usageKind === value}
                onClick={() => setUsageKind(value)}
                className={`rounded-lg px-3 py-1.5 text-xs font-bold transition-colors ${usageKind === value ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}
              >
                {label}
              </button>
            ))}
          </div>
        )}
      >
        {(() => {
          const rows = usageKind === 'medicine' ? report.mostUsedMedicines : report.mostUsedSupplies
          const top = rows[0]
          return (
            <div className="space-y-5">
              {top && (
                <div className="flex flex-wrap items-center gap-4 rounded-2xl border border-emerald-200 bg-emerald-50 px-5 py-4">
                  <MdMedication className="text-3xl text-emerald-600" />
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-bold text-emerald-700">{usageKind === 'medicine' ? 'Most used medicine' : 'Most used supply'}</p>
                    <p className="truncate text-xl font-black text-emerald-900">{top.name}</p>
                  </div>
                  <p className="text-right text-emerald-900"><span className="text-3xl font-black">{formatQty(top.total_used)}</span> <span className="text-sm font-semibold">{top.unit} across {top.visits} visit{top.visits === 1 ? '' : 's'}</span></p>
                </div>
              )}
              <HorizontalBarChart
                data={rows.slice(0, 8).map((row) => ({ label: row.name, value: Number(row.total_used) || 0 }))}
                valueFormatter={formatQty}
                emptyMessage={`No ${usageKind === 'medicine' ? 'medicines' : 'supplies'} were used in this period.`}
              />
              <MostUsedTable rows={rows} kindLabel={usageKind === 'medicine' ? 'Medicines' : 'Supplies'} />
            </div>
          )
        })()}
      </Section>

      <div>
        <p className="mb-3 text-xs font-black uppercase tracking-[0.2em] text-slate-400">Current Snapshot · Not Historical</p>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
          <StatCard label="Today Remaining" value={report.current.today_remaining || 0} icon={MdCalendarToday} />
          <StatCard label="Future Scheduled" value={report.current.future_confirmed || 0} icon={MdCalendarToday} />
          <StatCard label="Awaiting Approval" value={report.current.awaiting_approval || 0} icon={MdChecklist} />
          <StatCard label="Walk-in Queue" value={report.current.walkin_queue || 0} icon={MdGroups} />
        </div>
      </div>

      <Section title="Current Inventory Health" subtitle="Current stock snapshot. Batch expiry is tracked separately; this section does not pretend to be the inventory balance for the selected historical period.">
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">
          <StatCard
            label="Inventory Value (Cost)"
            value={formatMoney(report.inventory.cost_value ?? report.inventory.total_value)}
            helper={`${formatMoney(report.inventory.retail_value)} at selling price${Number(report.inventory.batches_without_cost || 0) > 0 ? ` · ${report.inventory.batches_without_cost} of ${report.inventory.batches_on_hand} batches have no unit cost` : ''}`}
            icon={MdInventory2}
          />
          <StatCard label="Out of Stock" value={report.inventory.out_of_stock || 0} tone="border-rose-200 bg-rose-50 text-rose-800" />
          <StatCard label="Low Stock" value={report.inventory.low_stock || 0} tone="border-amber-200 bg-amber-50 text-amber-800" />
          <StatCard label="Expired" value={report.inventory.expired || 0} tone="border-red-200 bg-red-50 text-red-800" />
          <StatCard label="Expiring in 30 Days" value={report.inventory.expiring_soon || 0} tone="border-violet-200 bg-violet-50 text-violet-800" />
        </div>
      </Section>

      <Section title="Inventory Movement" subtitle="Stock-ins, manual stock-outs, transfers, and clinical consumption for the selected period. Batch details remain available in Inventory Activity.">
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{report.stockReasons.length === 0 ? <p className="text-sm text-slate-400">No inventory movements for this period.</p> : report.stockReasons.map((row) => <div key={row.movement_type} className="rounded-2xl border border-slate-100 bg-slate-50 p-4"><p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{inventoryMovementLabel(row.movement_type)}</p><div className="mt-2 flex items-end justify-between"><p className="text-2xl font-black text-slate-900">{row.quantity}</p><p className="text-xs text-slate-500">{row.actions} actions</p></div></div>)}</div>
      </Section>
    </div>
  )
}

export default Admin_Reports

import useClinicRefresh from '../../hooks/useClinicRefresh'
import { useEffect, useMemo, useRef, useState } from 'react'
import { portalBaseForPath } from '../../utils/branchPortalPath.mjs'
import { Link, useLocation, useSearchParams } from 'react-router-dom'
import {
  MdAdd,
  MdEdit,
  MdDelete,
  MdWarningAmber,
  MdRefresh,
  MdSettings,
} from 'react-icons/md'
import Admin_PatientBooking from './Admin_PatientBooking'
import Modal from '../../components/ui/Modal'
import Pagination from '../../components/ui/Pagination'
import SystemSetupTabs, { SYSTEM_SETUP_TABS } from '../../components/system/SystemSetupTabs'
import StockRoomsManager from '../../components/system/StockRoomsManager'
import SetupTableActions, { SETUP_ACTION_BUTTON, SETUP_ACTION_CELL } from '../../components/system/SetupTableActions'
import useClientPagination from '../../hooks/useClientPagination'
import { LoadingState, ErrorState, EmptyState } from '../../components/ui/PageState'
import { useToast } from '../../components/ui/ToastProvider'
import {
  getSystemSetup,
  deleteAppointmentCancellationReason,
  saveAppointmentCancellationReason,
  deleteBillingServiceCategory,
  deleteInventorySupplier,
  deleteInventoryLocationType,
  deleteInventoryMovementReason,
  saveBillingServiceCategory,
  saveInventoryLocationType,
  saveInventoryMovementReason,
  saveInventorySupplier,
} from '../../services/admin.service'

const TABS = SYSTEM_SETUP_TABS.filter((item) => !['billing_setup', 'location_types'].includes(item.key))

const clinicLabel = (value) => value === 'derma' ? 'Dermatology' : 'General Medicine'
const parseSupplierClinics = (value) => String(value || '').split(',').map((entry) => entry.trim()).filter((entry) => ['medical','derma'].includes(entry))
const supplierClinicLabel = (value) => {
  const clinics = parseSupplierClinics(value)
  return clinics.length ? clinics.map(clinicLabel).join(', ') : '—'
}

const ReferenceManager = ({ type, rows, onReload, portalBase = '/admin' }) => {
  const referenceLocation = useLocation()
  const superAdminMode = referenceLocation.pathname.startsWith('/superadmin/')
  const workspaceBranch = referenceLocation.pathname.match(/^\/superadmin\/branches\/(\d+)(?:\/|$)/)
  const globalSetup = superAdminMode && !workspaceBranch
  const canEditReference = (row) => type !== 'movement_reasons' || (globalSetup
    ? row.branch_id == null
    : row.branch_id != null && (!workspaceBranch || Number(row.branch_id) === Number(workspaceBranch[1])))
  const canRemoveReference = (row) => canEditReference(row) && !(type === 'movement_reasons' && Number(row.is_system) === 1)
  const getUsage = (row) => Number(type === 'service_categories' ? row.service_count : type === 'cancellation_reasons' ? row.appointment_count : row.usage_count || 0)
  const deleteAction = (row) => getUsage(row) > 0 ? 'Deactivate' : 'Delete'
  const toast = useToast()
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState({})
  const [saving, setSaving] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [deleting, setDeleting] = useState(false)
  const [deleteError, setDeleteError] = useState('')


  const nameMaxLength = {
    service_categories: 120,
    suppliers: 160,
    location_types: 80,
    movement_reasons: 120,
    cancellation_reasons: 120,
  }[type] || 120

  const config = useMemo(() => ({
    cancellation_reasons: {
      title: 'Reason for Cancellation',
      plural: 'Reasons for Cancellation',
      singular: 'cancellation reason',
      save: saveAppointmentCancellationReason,
      description: 'Reusable reasons shown whenever a Patient, Admin, or Staff member cancels an appointment. “Other” is always available separately and requires an explanation.',
    },
    service_categories: {
      title: 'Service Category',
      plural: 'Service Categories',
      singular: 'service category',
      save: saveBillingServiceCategory,
      description: 'Categories only group actual services. They are shown alphabetically in Add Service; create bookable services under System Setup → Services & Pricing Setup → Services & Pricing.',
    },
    suppliers: {
      title: 'Supplier',
      plural: 'Suppliers',
      singular: 'supplier',
      save: saveInventorySupplier,
      description: 'Reusable supplier/company records with clinic assignment and contact details.',
    },
    location_types: {
      title: 'Storage Location',
      plural: 'Storage Locations',
      singular: 'storage location',
      save: saveInventoryLocationType,
      description: 'Reusable Storage Locations assigned directly to inventory items. Add at least one before creating inventory items.',
    },
    movement_reasons: {
      title: 'Movement Reason',
      plural: 'Movement Reasons',
      singular: 'movement reason',
      save: saveInventoryMovementReason,
      description: 'Add Stock In / Stock Out reasons for this clinic. Shared reasons are read-only. Changes to this clinic do not affect other branches.',
    },
  }[type]), [type])

  const pagination = useClientPagination(rows, { initialPageSize: 10, resetDeps: [type] })

  const close = () => {
    setEditing(null)
    setForm({})
  }

  const open = (row = null) => {
    setEditing(row)
    if (type === 'cancellation_reasons') {
      setForm({
        name: row?.label || '',
        is_active: row ? Number(row.is_active) : 1,
      })
    }
    if (type === 'service_categories') {
      setForm({
        name: row?.name || '',
        clinic_type: row?.clinic_type || 'medical',
        is_active: row ? Number(row.is_active) : 1,
      })
    }
    if (type === 'suppliers') {
      setForm({
        name: row?.name || '',
        contact_person: row?.contact_person || '',
        contact_number: row?.contact_number || '',
        address: row?.address || '',
        clinics: parseSupplierClinics(row?.category),
        is_active: row ? Number(row.is_active) : 1,
      })
    }
    if (type === 'location_types') {
      setForm({
        name: row?.name || '',
        is_active: row ? Number(row.is_active) : 1,
        sort_order: row?.sort_order ?? 0,
      })
    }
    if (type === 'movement_reasons') {
      setForm({
        name: row?.name || '',
        movement_type: row?.movement_type || 'in',
        requires_batch: row ? Number(row.requires_batch) : 0,
        is_active: row ? Number(row.is_active) : 1,
        is_system: row ? Number(row.is_system) : 0,
        code: row?.code || '',
      })
    }
  }

  const save = async () => {
    if (!String(form.name || '').trim()) return toast.warning(`Enter a ${config.singular} name.`)
    if (type === 'suppliers' && !(form.clinics || []).length) return toast.warning('Select at least one clinic.')
    setSaving(true)
    try {
      const payload = type === 'cancellation_reasons'
        ? { label: String(form.name).trim(), is_active: form.is_active }
        : { ...form, name: String(form.name).trim() }
      await config.save(payload, editing?.id || null)
      toast.success(`${config.title} ${editing ? 'updated' : 'added'}.`)
      close()
      await onReload()
    } catch (err) {
      toast.error(err.message || `Could not save ${config.singular}.`)
    } finally {
      setSaving(false)
    }
  }


  const requestDelete = (row) => {
    if (!canEditReference(row)) return
    setDeleteError('')
    setDeleteTarget(row)
  }

  const referencePayload = (row,isActive) => type === 'cancellation_reasons'
    ? {label:row.label,is_active:isActive}
    : type === 'suppliers'
      ? {name:row.name,contact_person:row.contact_person,contact_number:row.contact_number,address:row.address,clinics:parseSupplierClinics(row.category),is_active:isActive}
      : {...row,is_active:isActive}

  const confirmDelete = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const handlers = {
        service_categories: deleteBillingServiceCategory,
        cancellation_reasons: deleteAppointmentCancellationReason,
        suppliers: deleteInventorySupplier,
        location_types: deleteInventoryLocationType,
        movement_reasons: deleteInventoryMovementReason,
      }
      let result
      if (getUsage(deleteTarget) > 0) {
        result = await config.save(referencePayload(deleteTarget,0),deleteTarget.id)
        if (Number(result?.is_active) !== 0) throw new Error('The server did not confirm deactivation.')
      } else {
        result = await handlers[type](deleteTarget.id)
        if (result?.deleted !== true && result?.deactivated !== true) throw new Error('The server returned an outdated removal response. Check that the updated backend has deployed successfully, then refresh this list.')
      }
      toast.success(result?.message || (result?.deleted ? `${config.title} permanently deleted.` : `${config.title} deactivated.`))
      setDeleteTarget(null)
      await onReload()
    } catch (err) {
      setDeleteError(err.message || `Could not update ${config.singular}.`)
      toast.error(err.message || `Could not update ${config.singular}.`)
    } finally {
      setDeleting(false)
    }
  }

  const reactivate = async (row) => {
    try {
      const result = await config.save(referencePayload(row,1),row.id)
      if(Number(result?.is_active)!==1) throw new Error('The server did not confirm reactivation.')
      toast.success(`${config.title} reactivated.`)
      await onReload()
    } catch(err) { toast.error(err.message || `Could not reactivate ${config.singular}.`) }
  }

  return (
    <section className="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5">
        <div>
          <h2 className="font-black text-slate-900">{config.plural}</h2>
          <p className="mt-1 max-w-3xl text-sm text-slate-500">{config.description}</p>
        </div>
        <div className="flex flex-wrap gap-2">
          {type === 'service_categories' && <Link className="button-secondary" to={`${portalBase}/system-setup/billing/services`}>Manage Services & Pricing</Link>}
          {<button type="button" className="button-primary" onClick={() => open()}><MdAdd /> {type === 'movement_reasons' && !globalSetup ? 'Add Branch Reason' : `Add ${config.title}`}</button>}
        </div>
      </div>

      {!rows.length ? (
        <div className="p-5"><EmptyState title={`No ${config.plural.toLowerCase()} yet`} description={type === 'movement_reasons' ? 'You can add Stock In or Stock Out reasons for this clinic. Shared Super Admin reasons will also appear here when available.' : 'Add the first reusable option.'} /></div>
      ) : (
        <div>
          <div className="overflow-x-auto">
          <table className={`w-full text-sm ${type === 'suppliers' ? 'min-w-[1160px]' : type === 'movement_reasons' ? 'min-w-[950px]' : 'min-w-[820px]'}`}>
            <thead className="bg-slate-50 text-left text-xs uppercase tracking-wide text-slate-400">
              <tr>
                <th className="px-5 py-3">Name</th>
                {type === 'cancellation_reasons' && <><th className="px-5 py-3">Used By</th></>}
                {type === 'service_categories' && <th className="px-5 py-3">Clinic</th>}
                {type === 'service_categories' && <th className="px-5 py-3">Used By</th>}
                {type === 'suppliers' && <th className="px-5 py-3">Contact</th>}
                {type === 'suppliers' && <th className="px-5 py-3">Address</th>}
                {type === 'suppliers' && <th className="px-5 py-3">Clinic</th>}
                {type === 'movement_reasons' && <th className="px-5 py-3">Movement</th>}
                {type === 'movement_reasons' && <th className="px-5 py-3">Batch Rule</th>}
                <th className="min-w-[100px] px-5 py-3">Status</th>
                <th className={SETUP_ACTION_CELL}>Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {pagination.pageItems.map((row) => (
                <tr key={row.id} className="align-middle">
                  <td className="min-w-[180px] px-5 py-4 font-semibold text-slate-800 break-words">{row.label || row.name}{type === 'movement_reasons' && <span className="ml-2 text-xs font-normal text-slate-400">{row.branch_id == null ? 'Shared' : 'This clinic'}</span>}</td>
                  {type === 'cancellation_reasons' && <><td className="px-5 py-4 text-slate-500">{Number(row.appointment_count || 0)} appointment{Number(row.appointment_count || 0) === 1 ? '' : 's'}</td></>}
                  {type === 'service_categories' && <td className="px-5 py-4 text-slate-500">{clinicLabel(row.clinic_type)}</td>}
                  {type === 'service_categories' && <td className="px-5 py-4 text-slate-500">{Number(row.service_count || 0)} service{Number(row.service_count || 0) === 1 ? '' : 's'}</td>}
                  {type === 'suppliers' && <td className="px-5 py-4 text-slate-500"><p className="font-semibold text-slate-700">{row.contact_person || '—'}</p><p className="mt-1 text-xs">{row.contact_number || 'No contact number'}</p></td>}
                  {type === 'suppliers' && <td className="max-w-xs px-5 py-4 text-slate-500">{row.address || '—'}</td>}
                  {type === 'suppliers' && <td className="px-5 py-4 text-slate-500">{supplierClinicLabel(row.category)}</td>}
                  {type === 'movement_reasons' && <td className="px-5 py-4 text-slate-500"><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${row.movement_type === 'in' ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'}`}>{row.movement_type === 'in' ? 'Stock In' : 'Stock Out'}</span></td>}
                  {type === 'movement_reasons' && <td className="px-5 py-4 text-slate-500">{Number(row.requires_batch) === 1 ? 'Exact batch required' : 'Standard batch flow'}</td>}
                  <td className="px-5 py-4">
                    <span className={`rounded-full px-2.5 py-1 text-xs font-bold ${Number(row.is_active) === 1 ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>
                      {Number(row.is_active) === 1 ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td className={SETUP_ACTION_CELL}>
                    <SetupTableActions
                      note={!canEditReference(row) ? (globalSetup ? 'Managed by branch' : 'Shared · read only') : null}
                      primary={canEditReference(row) ? <button type="button" className={SETUP_ACTION_BUTTON} onClick={() => open(row)}><MdEdit /> Edit</button> : null}
                      secondary={canRemoveReference(row) && Number(row.is_active) === 0 && getUsage(row) > 0
                        ? <button type="button" className={SETUP_ACTION_BUTTON} onClick={() => reactivate(row)}>Reactivate</button>
                        : canRemoveReference(row) && (Number(row.is_active) === 1 || getUsage(row) === 0)
                          ? <button type="button" className={`${SETUP_ACTION_BUTTON} ${getUsage(row) === 0 ? '!border-rose-200 !text-rose-600 hover:!bg-rose-50' : ''}`} onClick={() => requestDelete(row)}><MdDelete /> {deleteAction(row)}</button>
                          : null}
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
          <Pagination {...pagination} total={rows.length} pageSizeOptions={[10, 25, 50]} />
        </div>
      )}

      <Modal open={Boolean(editing) || Boolean(form.name !== undefined && Object.keys(form).length)} onClose={close} title={`${editing ? 'Edit' : 'Add'} ${config.title}`} size="md">
        <div className="space-y-4">
          <label className="block">
